// 10 chapters, 40 missions, 827 spoken lines (ids match the recording manifest).
export const SCRIPT = {"chapters":[{"n":1,"title":"The Garage","intro":"Planned gameplay: 180 minutes. Kit returns on a Monday; chapter 2's memorial supper is the following Saturday. Later Saturdays are separate weeks. Missions advance the calendar on completion so travel and rest never race a real-world deadline.","missions":[{"id":"01.01","title":"Shutters Up","chapter":1,"target":45,"location":"Vale Garage","unlock":"new campaign","objectives":"enter the office; identify three customer jobs from tags; inspect the pickup; telephone the generator customer; open the yard shutters.","gameplay":"10 minutes examining the inherited workspace, 20 inspecting and testing the truck and generator, 10 organizing tools, 5 for scenes. Tutorial prompts use existing inspection and interaction controls. No timed failure.","success":"GARAGE_OPEN. The customer agrees to collection after the repair. Exit to 01.02.","recovery":"wrong inspection answers reveal the relevant part instead of failing the mission. Forgotten objects are highlighted only after the player requests help.","choice":"","notes":[],"scenes":[{"key":"01.01.A","title":"The keys","kind":"Opening cinematic","stage":"Black screen. A key turns twice before the door opens. Camera stays behind Kit as she puts an overnight bag on the office chair. June's coat remains on its hook. No music until the shutters lift.","notes":[],"lines":[{"id":"LH-01-01-A-001","sp":"KIT","dir":"to herself; practical","text":"Office key. Yard key. Three keys to something nobody bothered to label."},{"id":"LH-01-01-A-002","sp":"ELLIS","dir":"from the doorway; tentative","text":"Big brass one's the fuel cage."},{"id":"LH-01-01-A-003","sp":"KIT","dir":"without turning","text":"I didn't ask you in."},{"id":"LH-01-01-A-004","sp":"ELLIS","dir":"matter-of-fact","text":"I'm still outside."},{"id":"LH-01-01-A-005","sp":"KIT","dir":"turning; recognition","text":"Ellis?"},{"id":"LH-01-01-A-006","sp":"ELLIS","dir":"small smile","text":"You got taller."},{"id":"LH-01-01-A-007","sp":"KIT","dir":"dry","text":"You got a beard. Neither of us should sound surprised."},{"id":"LH-01-01-A-008","sp":"ELLIS","dir":"gentle","text":"I came for the generator. Mrs. Bell's waiting."},{"id":"LH-01-01-A-009","sp":"KIT","dir":"looking at the stacked jobs","text":"Of course somebody's waiting."}],"journal":""},{"key":"01.01.B","title":"A customer's name","kind":"Interactive office call","stage":"Trigger: pick up the telephone. Kit can inspect each tag before calling. The customer is Lorna, not a new anonymous voice.","notes":[],"lines":[{"id":"LH-01-01-B-001","sp":"LORNA","dir":"telephone; busy kitchen behind her","text":"Bell's Bakery."},{"id":"LH-01-01-B-002","sp":"KIT","dir":"professional","text":"Kit Vale. I'm calling about your generator."},{"id":"LH-01-01-B-003","sp":"LORNA","dir":"after a beat","text":"I'm sorry about June."},{"id":"LH-01-01-B-004","sp":"KIT","dir":"quickly moving on","text":"The tag says Lauren."},{"id":"LH-01-01-B-005","sp":"LORNA","dir":"dry","text":"She called me that for seven years. Generator never seemed to mind."},{"id":"LH-01-01-B-006","sp":"KIT","dir":"checking her notes","text":"Does it stop when it gets warm?"},{"id":"LH-01-01-B-007","sp":"LORNA","dir":"precise","text":"Twenty minutes, then it coughs and dies. It runs the cold room during outages."},{"id":"LH-01-01-B-008","sp":"KIT","dir":"considering","text":"I'll test it before I promise a collection time."},{"id":"LH-01-01-B-009","sp":"LORNA","dir":"relieved","text":"Thank you. I can plan around an honest answer."}],"journal":""},{"key":"01.01.C","title":"Open","kind":"End cinematic","stage":"Trigger: all inspections complete and shutter opened. Daylight crosses a rectangle of cleaner concrete where June used to park.","notes":[],"lines":[{"id":"LH-01-01-C-001","sp":"ELLIS","dir":"watching the light","text":"She'd have had that up before sunrise."},{"id":"LH-01-01-C-002","sp":"KIT","dir":"quiet","text":"She'd also have left six invoices under a sandwich."},{"id":"LH-01-01-C-003","sp":"ELLIS","dir":"a breath of laughter","text":"Those might be in the fridge."},{"id":"LH-01-01-C-004","sp":"KIT","dir":"almost smiling","text":"Don't make that a real possibility."},{"id":"LH-01-01-C-005","sp":"ELLIS","dir":"offering","text":"I can stay."},{"id":"LH-01-01-C-006","sp":"KIT","dir":"measured","text":"Put the kettle on. Then show me which jobs she already charged for."}],"journal":"Open work is still work. Start with the truck."}]},{"id":"01.02","title":"Receipt on the Box","chapter":1,"target":45,"location":"garage and water pump","unlock":"GARAGE_OPEN","objectives":"test the old battery; find the replacement; install it safely; fill water; check oil and coolant; secure a recovery kit.","gameplay":"25 minutes hands-on maintenance, 10 finding supplies, 5 short test drive, 5 dialogue. Battery installation is required; replacing other worn parts is optional.","success":"TRUCK_READY. Kit discovers a purchase dated the day before June died.","recovery":"incorrect battery placement gives an interaction correction. A damaged test-drive truck can be repaired with the garage's marked tutorial supplies.","choice":"","notes":[],"scenes":[{"key":"01.02.A","title":"Yesterday's warranty","kind":"Interactive discovery","stage":"Kit pulls a battery carton from beneath the bench. A receipt is taped to it. Ellis holds the torch.","notes":[],"lines":[{"id":"LH-01-02-A-001","sp":"KIT","dir":"reading","text":"Thursday. She bought this Thursday."},{"id":"LH-01-02-A-002","sp":"ELLIS","dir":"careful","text":"Said the old one was finished."},{"id":"LH-01-02-A-003","sp":"KIT","dir":"a brittle joke","text":"She could diagnose a battery. That must have been comforting."},{"id":"LH-01-02-A-004","sp":"ELLIS","dir":"not taking the bait","text":"Receipt's still good."},{"id":"LH-01-02-A-005","sp":"KIT","dir":"looking away","text":"I can see that."},{"id":"LH-01-02-A-006","sp":"ELLIS","dir":"softly","text":"I'll check the pump."},{"id":"LH-01-02-A-007","sp":"KIT","dir":"after him","text":"Ellis."},{"id":"LH-01-02-A-008","sp":"ELLIS","dir":"stopping","text":"Yeah?"},{"id":"LH-01-02-A-009","sp":"KIT","dir":"recovering her working voice","text":"Leave the light."}],"journal":""},{"key":"01.02.B","title":"It catches","kind":"End cinematic","stage":"Trigger: successful start after replacement. Engine sound resolves from an uneven crank to idle. Kit listens longer than necessary.","notes":[],"lines":[{"id":"LH-01-02-B-001","sp":"KIT","dir":"under her breath","text":"There you are."},{"id":"LH-01-02-B-002","sp":"ELLIS","dir":"outside the window","text":"Sounds all right."},{"id":"LH-01-02-B-003","sp":"KIT","dir":"listening","text":"Belt whistles. Something's knocking in the bed. The rest is an argument with my mother."},{"id":"LH-01-02-B-004","sp":"ELLIS","dir":"warm","text":"Familiar sort of argument."},{"id":"LH-01-02-B-005","sp":"KIT","dir":"switching off","text":"I was going to sell it."},{"id":"LH-01-02-B-006","sp":"ELLIS","dir":"neutral","text":"Still could."},{"id":"LH-01-02-B-007","sp":"KIT","dir":"firm, tired","text":"I know. I need everybody to stop telling me what I could do for ten minutes."},{"id":"LH-01-02-B-008","sp":"ELLIS","dir":"accepting","text":"All right. Nine minutes, then I'll ask about the generator."}],"journal":"Reliable enough to leave. Check it again before the longer road."}]},{"id":"01.03","title":"The Message","chapter":1,"target":45,"location":"garage","unlock":"TRUCK_READY","objectives":"listen to Alma's message; identify the workbench as a door; remove tools and brackets; protect the pencil marks; secure the door to the pickup.","gameplay":"10 office investigation, 25 cargo and workshop interaction, 5 calling Alma, 5 scenes. Loading the actual door teaches large-item securing.","success":"DOOR_LOADED. Optional PENCIL_PROTECTED if no cleaning product is applied to the jamb.","recovery":"the door cannot be destroyed by tutorial interactions. A loosened strap must be retied before departure; the game explains why.","choice":"","notes":[],"scenes":[{"key":"01.03.A","title":"Voicemail","kind":"Recorded audio","stage":"Trigger: press playback on June's answering machine. Alma's message plays cleanly after a short mechanical click.","notes":[],"lines":[{"id":"LH-01-03-A-001","sp":"ALMA","dir":"voicemail; clear and unhurried","text":"June, it's Alma Reyes. I'd like my front door back. We're doing supper Saturday at the motel. You can bring it then. Call me before you put anything wet on the paint."},{"id":"LH-01-03-A-002","sp":"KIT","dir":"to Ellis","text":"Front door?"},{"id":"LH-01-03-A-003","sp":"ELLIS","dir":"looking at the bench","text":"Yellow one?"},{"id":"LH-01-03-A-004","sp":"KIT","dir":"following his gaze","text":"You're kidding."},{"id":"LH-01-03-A-005","sp":"ELLIS","dir":"uneasy","text":"She meant to take it over."},{"id":"LH-01-03-A-006","sp":"KIT","dir":"seeing the jamb","text":"There are heights on this."},{"id":"LH-01-03-A-007","sp":"ELLIS","dir":"quiet","text":"I know."}],"journal":""},{"key":"01.03.B","title":"The call back","kind":"Interactive phone scene","stage":"","notes":[],"lines":[{"id":"LH-01-03-B-001","sp":"ALMA","dir":"telephone","text":"Reyes."},{"id":"LH-01-03-B-002","sp":"KIT","dir":"awkward introduction","text":"Kit Vale. June's daughter. I found your message."},{"id":"LH-01-03-B-003","sp":"ALMA","dir":"a small pause","text":"I heard about your mother. I'm sorry."},{"id":"LH-01-03-B-004","sp":"KIT","dir":"holding herself together","text":"Thank you. I've found the door."},{"id":"LH-01-03-B-005","sp":"ALMA","dir":"attentive","text":"Has it still got the frame?"},{"id":"LH-01-03-B-006","sp":"KIT","dir":"looking","text":"One side. Pencil marks up the edge."},{"id":"LH-01-03-B-007","sp":"ALMA","dir":"firm","text":"Bring that side."},{"id":"LH-01-03-B-008","sp":"KIT","dir":"offering money","text":"I can pay for the rest if it's damaged."},{"id":"LH-01-03-B-009","sp":"ALMA","dir":"patient","text":"Bring what you've got first. We'll see it in daylight."},{"id":"LH-01-03-B-010","sp":"KIT","dir":"relieved by a concrete job","text":"Saturday?"},{"id":"LH-01-03-B-011","sp":"ALMA","dir":"ordinary warmth","text":"Earlier if you want tea. Same room I've had for twelve years."}],"journal":""},{"key":"01.03.C","title":"Beneath the bench","kind":"Optional recording","stage":"Trigger: inspect the cassette beside the battery shelf. This is a domestic message, recorded the week before June died. Player may replay from journal.","notes":[],"lines":[{"id":"LH-01-03-C-001","sp":"JUNE","dir":"tape; restarting herself","text":"Kit. It's me. Obviously."},{"id":"LH-01-03-C-002","sp":"JUNE","dir":"trying for ordinary","text":"Your socket set turned up. Under the bench, where you said it wasn't. We were both right in a technical sense."},{"id":"LH-01-03-C-003","sp":"JUNE","dir":"hesitant","text":"About selling. I heard you."},{"id":"LH-01-03-C-004","sp":"JUNE","dir":"changing subject","text":"Battery's under there too. Keep it upright. Receipt's taped to the box."},{"id":"LH-01-03-C-005","sp":"KIT","dir":"after the tape stops; barely audible","text":"You could have sent it."}],"journal":""}]},{"id":"01.04","title":"A Door on the Highway","chapter":1,"target":45,"location":"garage to Mercy Motel, 12 road kilometres","unlock":"DOOR_LOADED","objectives":"plot the motel route; inspect straps at the pull-off; help Del with his groceries or arrange Ellis to collect them; deliver the door.","gameplay":"15 driving, 10 roadside load check, 10 Del interaction and route discovery, 10 destination scenes.","success":"","recovery":"if cargo detaches, retrieval marker persists. If truck is disabled, Ellis lends a tow and the garage ledger records a modest repair debt. No repeated cash grind.","choice":"help Del directly sets DEL_HELPED; telephone Ellis sets DEL_ASSISTED. Neither blocks the story.","notes":[],"scenes":[{"key":"01.04.A","title":"The pull-off","kind":"Branching roadside exchange","stage":"Del has set groceries on a bench. His promised lift did not arrive.","notes":[],"lines":[{"id":"LH-01-04-A-001","sp":"DEL","dir":"looking at the door","text":"Moving house?"},{"id":"LH-01-04-A-002","sp":"KIT","dir":"checking a strap","text":"Only the entrance."},{"id":"LH-01-04-A-003","sp":"DEL","dir":"approving","text":"Sensible. Start small."},{"id":"LH-01-04-A-004","sp":"KIT","dir":"noticing his bags","text":"Need a lift?"},{"id":"LH-01-04-A-005","sp":"DEL","dir":"practical","text":"Motel. These need the fridge. I can wait longer than the butter."},{"id":"LH-01-04-A-006","sp":"KIT","dir":"opening passenger door","text":"Put the bags by your feet.","branch":"DRIVE"},{"id":"LH-01-04-A-007","sp":"DEL","dir":"settling","text":"I'll pay you when we get there.","branch":"DRIVE"},{"id":"LH-01-04-A-008","sp":"KIT","dir":"checking mirrors","text":"Tell me which turn.","branch":"DRIVE"},{"id":"LH-01-04-A-009","sp":"KIT","dir":"dialling","text":"I've got no safe room with this load. Ellis can fetch you.","branch":"CALL"},{"id":"LH-01-04-A-010","sp":"DEL","dir":"accepting","text":"Tell him about the butter before he decides to stop for petrol.","branch":"CALL"}],"journal":""},{"key":"01.04.B","title":"The yellow jamb","kind":"Destination cinematic","stage":"Alma lifts one corner of the wrapping. Camera finds the pencil marks only when her fingers do.","notes":["Chapter exit: Kit moves her overnight bag out of the truck. Fade to 'Friday'."],"lines":[{"id":"LH-01-04-B-001","sp":"ALMA","dir":"recognizing it","text":"Here. That dent. Nico threw a horseshoe backwards."},{"id":"LH-01-04-B-002","sp":"KIT","dir":"curious despite herself","text":"Was he meant to?"},{"id":"LH-01-04-B-003","sp":"ALMA","dir":"dry","text":"Apparently it was a scientific question."},{"id":"LH-01-04-B-004","sp":"KIT","dir":"touching a high mark","text":"This one must be him."},{"id":"LH-01-04-B-005","sp":"ALMA","dir":"pleased to correct her","text":"My sister. Forty-six. Took her shoes off to see if she'd shrunk."},{"id":"LH-01-04-B-006","sp":"KIT","dir":"careful","text":"I haven't cleaned the edge."},{"id":"LH-01-04-B-007","sp":"ALMA","dir":"if PENCIL_PROTECTED; grateful","text":"Good. You've left everybody where they stood.","cond":"PENCIL_PROTECTED"},{"id":"LH-01-04-B-008","sp":"ALMA","dir":"if not protected; contained","text":"It's faint, but it's there. Leave it now.","cond":"not protected"},{"id":"LH-01-04-B-009","sp":"KIT","dir":"looking at the motel","text":"Where do you want it hung?"},{"id":"LH-01-04-B-010","sp":"ALMA","dir":"lifting the trestles","text":"Nobody's hanging it. We need a table."},{"id":"LH-01-04-B-011","sp":"KIT","dir":"taking one end","text":"What time Saturday?"},{"id":"LH-01-04-B-012","sp":"ALMA","dir":"matter-of-fact","text":"Come Friday. The chairs won't collect themselves."}],"journal":""}]}]},{"n":2,"title":"The People Who Waited","intro":"Planned gameplay: 240 minutes. Friday through the first Saturday. A social and logistics chapter with four distinct jobs.","missions":[{"id":"02.01","title":"Cold Room","chapter":2,"target":60,"location":"motel, garage, bakery, 18 road kilometres","unlock":"","objectives":"diagnose Lorna's generator fuel vent; clean the vent and test under load; deliver generator; collect bread for supper.","gameplay":"20 repair and load testing, 20 driving and navigation, 10 bakery delivery, 10 dialogue and preparation.","success":"BAKERY_HELPED; FLOUR_CONTACT. Repair is measured by a sustained in-game load test, not a real-time wait.","recovery":"spare vent cap is available at the garage. The final generator test can be retried without buying another unit.","choice":"","notes":[],"scenes":[{"key":"02.01.A","title":"The written name","kind":"Bakery arrival","stage":"","notes":[],"lines":[{"id":"LH-02-01-A-001","sp":"LORNA","dir":"looking at the corrected tag","text":"You put my name right."},{"id":"LH-02-01-A-002","sp":"KIT","dir":"unloading","text":"Easier than repairing the wrong woman's generator."},{"id":"LH-02-01-A-003","sp":"LORNA","dir":"testing the handle","text":"What's wrong with it?"},{"id":"LH-02-01-A-004","sp":"KIT","dir":"explaining while showing","text":"Tank vent's blocked. It draws a vacuum, starves, then behaves again when you open the cap."},{"id":"LH-02-01-A-005","sp":"LORNA","dir":"a rueful laugh","text":"June called that a temperament."},{"id":"LH-02-01-A-006","sp":"KIT","dir":"not smiling yet","text":"It's a hole. It needs to be open."},{"id":"LH-02-01-A-007","sp":"LORNA","dir":"kindly","text":"Well, you've opened it."},{"id":"LH-02-01-A-008","sp":"KIT","dir":"moving the conversation","text":"Alma asked about bread."},{"id":"LH-02-01-A-009","sp":"LORNA","dir":"pointing","text":"Those two crates. Ugly loaves on top are yours."}],"journal":""},{"key":"02.01.B","title":"Before the ovens","kind":"Departure exchange","stage":"Lorna hands Kit an invoice marked 'settled by service'.","notes":[],"lines":[{"id":"LH-02-01-B-001","sp":"KIT","dir":"checking","text":"You haven't charged for the bread."},{"id":"LH-02-01-B-002","sp":"LORNA","dir":"practical","text":"Generator works. Fridge stays cold. We can both stop keeping score for today."},{"id":"LH-02-01-B-003","sp":"KIT","dir":"hesitant","text":"Did she charge you twice?"},{"id":"LH-02-01-B-004","sp":"LORNA","dir":"meeting her eyes","text":"Once. Took three months. I was angry about that, too."},{"id":"LH-02-01-B-005","sp":"KIT","dir":"quiet","text":"People keep giving me the good version."},{"id":"LH-02-01-B-006","sp":"LORNA","dir":"plain","text":"Ask a different question."},{"id":"LH-02-01-B-007","sp":"KIT","dir":"thinking","text":"What should I ask?"},{"id":"LH-02-01-B-008","sp":"LORNA","dir":"after a beat","text":"Who was left waiting?"}],"journal":""}]},{"id":"02.02","title":"Six Chairs and a Stove","chapter":2,"target":60,"location":"rental shed, camp and motel, 24 road kilometres","unlock":"","objectives":"collect six mismatched chairs; obtain stove from camp; carry lamp fuel safely; arrange accessible seating.","gameplay":"20 multi-stop collection, 15 cargo balancing, 15 setup with Del, 10 scene time.","success":"SUPPER_READY. Optional ACCESSIBLE_TABLE if a clear approach and stable chair are chosen.","recovery":"broken chair can be repaired with shed timber; additional chairs remain available. Fuel spill replacement comes from the camp at cost recorded against supper donations.","choice":"","notes":[],"scenes":[{"key":"02.02.A","title":"The camp stove","kind":"Interactive handover","stage":"","notes":[],"lines":[{"id":"LH-02-02-A-001","sp":"MANNY","dir":"warning as Kit lifts","text":"Take the legs out first. They fold at the wrong moment."},{"id":"LH-02-02-A-002","sp":"KIT","dir":"setting it down","text":"That sounds like information worth leading with."},{"id":"LH-02-02-A-003","sp":"MANNY","dir":"cheerful","text":"You're the first person who's tried lifting before asking what it weighs."},{"id":"LH-02-02-A-004","sp":"KIT","dir":"dry","text":"My family's got a history of poor questions."},{"id":"LH-02-02-A-005","sp":"MANNY","dir":"turning serious","text":"June brought that out of Mercy. It was ours."},{"id":"LH-02-02-A-006","sp":"KIT","dir":"looking at the stove","text":"Did she return everything?"},{"id":"LH-02-02-A-007","sp":"MANNY","dir":"no performance","text":"She returned the stove."},{"id":"LH-02-02-A-008","sp":"KIT","dir":"hearing the distinction","text":"Right."},{"id":"LH-02-02-A-009","sp":"MANNY","dir":"handing her the legs","text":"Bring it back with the legs. Everybody forgets them."}],"journal":""},{"key":"02.02.B","title":"Place at the table","kind":"Setup scene","stage":"","notes":[],"lines":[{"id":"LH-02-02-B-001","sp":"DEL","dir":"moving a chair","text":"Leave that end clear."},{"id":"LH-02-02-B-002","sp":"KIT","dir":"measuring with her hand","text":"We lose a seat."},{"id":"LH-02-02-B-003","sp":"DEL","dir":"patient","text":"We gain somewhere for Edie to get her knee under."},{"id":"LH-02-02-B-004","sp":"ALMA","dir":"arriving with cloths","text":"And someone can borrow my chair while I'm serving."},{"id":"LH-02-02-B-005","sp":"KIT","dir":"if ACCESSIBLE_TABLE; pleased","text":"I left a straight path from the room.","cond":"ACCESSIBLE_TABLE"},{"id":"LH-02-02-B-006","sp":"ALMA","dir":"if ACCESSIBLE_TABLE","text":"Thank you. She'll notice before she says anything.","cond":"ACCESSIBLE_TABLE"},{"id":"LH-02-02-B-007","sp":"DEL","dir":"if not accessible; teaching","text":"Try sitting in it before you decide it fits.","cond":"not accessible"},{"id":"LH-02-02-B-008","sp":"KIT","dir":"if not accessible; correcting","text":"All right. Pass the short table.","cond":"not accessible"},{"id":"LH-02-02-B-009","sp":"ALMA","dir":"looking at the door","text":"Watch the pencil side with that clamp."}],"journal":""}]},{"id":"02.03","title":"Everybody's Version","chapter":2,"target":60,"location":"supper and motel yard","unlock":"","objectives":"serve three tables; speak to Nico, Fern and Ellis; hear the county excerpt; choose whether to ask about June publicly or privately.","gameplay":"25 player-directed conversations, 15 serving and clearing, 10 exploring photographs, 10 cinematic transitions.","success":"ELLIS_TICKET_LEAD. Choice PUBLIC_QUESTION changes discomfort and later acknowledgments, not evidence availability.","recovery":"missed conversations remain available after supper. No required clue is hidden behind a dialogue timer.","choice":"","notes":[],"scenes":[{"key":"02.03.A","title":"Toast","kind":"Ensemble cinematic","stage":"Alma taps a spoon against a mug. No one rises for a speech.","notes":[],"lines":[{"id":"LH-02-03-A-001","sp":"ALMA","dir":"to the room","text":"Food's on the yellow door. Leave the blue dish. Somebody's looking for it."},{"id":"LH-02-03-A-002","sp":"MANNY","dir":"calling from a chair","text":"Is that the official toast?"},{"id":"LH-02-03-A-003","sp":"ALMA","dir":"without pause","text":"It is if you stop talking."},{"id":"LH-02-03-A-004","sp":"NICO","dir":"to Kit; low","text":"She rehearsed that in the car."},{"id":"LH-02-03-A-005","sp":"KIT","dir":"a small laugh","text":"Did she?"},{"id":"LH-02-03-A-006","sp":"NICO","dir":"fond","text":"No. She'll say she did."},{"id":"LH-02-03-A-007","sp":"FERN","dir":"at the next table","text":"June once brought me a compressor with the handle tied on with her belt."},{"id":"LH-02-03-A-008","sp":"KIT","dir":"interested","text":"Did she get the belt back?"},{"id":"LH-02-03-A-009","sp":"FERN","dir":"smiling","text":"Charged it on the invoice. Itemized."},{"id":"LH-02-03-A-010","sp":"ELLIS","dir":"watching Kit","text":"That's the June people remember."}],"journal":""},{"key":"02.03.B","title":"The famous call","kind":"Radio playback","stage":"Trigger: Inez plays a short archive excerpt at a guest's request. Do not loop it.","notes":[],"lines":[{"id":"LH-02-03-B-001","sp":"INEZ","dir":"introducing the source","text":"County inquiry extract. Clearance day, afternoon. That's the archive label, not my description."},{"id":"LH-02-03-B-002","sp":"JUNE","dir":"archival; ordinary dispatch delivery","text":"Mercy empty. Returning to depot."},{"id":"LH-02-03-B-003","sp":"KIT","dir":"after the click","text":"She never played that at home."},{"id":"LH-02-03-B-004","sp":"KIT","dir":"to the table","text":"Did she actually say she'd collected everybody?","branch":"PUBLIC_QUESTION"},{"id":"LH-02-03-B-005","sp":"NICO","dir":"firm","text":"This isn't a good place to ask people to testify.","branch":"PUBLIC_QUESTION"},{"id":"LH-02-03-B-006","sp":"KIT","dir":"caught","text":"I didn't mean it like that.","branch":"PUBLIC_QUESTION"},{"id":"LH-02-03-B-007","sp":"ALMA","dir":"steady","text":"Then save the question. Eat while it's hot.","branch":"PUBLIC_QUESTION"},{"id":"LH-02-03-B-008","sp":"KIT","dir":"quietly to Inez","text":"Can I listen to the rest?","branch":"PRIVATE_QUESTION"},{"id":"LH-02-03-B-009","sp":"INEZ","dir":"low","text":"What I have is nineteen seconds. Come by the station.","branch":"PRIVATE_QUESTION"},{"id":"LH-02-03-B-010","sp":"ELLIS","dir":"approaching once others turn away","text":"There's a weigh ticket. Come and see me tomorrow."}],"journal":""}]},{"id":"02.04","title":"After the Plates","chapter":2,"target":60,"location":"motel to garage and weigh-station approach, 20 road kilometres","unlock":"","objectives":"return camp stove; take Ellis home; log the ticket clue; close the garage; inspect the proposed route.","gameplay":"25 night driving, 15 returns, 10 preparation for remote work, 10 scenes.","success":"WEIGH_STATION_UNLOCKED. Calendar advances to the next morning.","recovery":"low fuel reveals a nearby paid pump. Running dry permits tow recovery without losing the ticket lead.","choice":"","notes":[],"scenes":[{"key":"02.04.A","title":"Dishes in the truck","kind":"Passenger scene","stage":"","notes":[],"lines":[{"id":"LH-02-04-A-001","sp":"ELLIS","dir":"watching the bed through the mirror","text":"That sound."},{"id":"LH-02-04-A-002","sp":"KIT","dir":"attentive","text":"Stove?"},{"id":"LH-02-04-A-003","sp":"ELLIS","dir":"remembering","text":"Plates used to do that under the tarpaulin."},{"id":"LH-02-04-A-004","sp":"KIT","dir":"careful","text":"On her truck?"},{"id":"LH-02-04-A-005","sp":"ELLIS","dir":"yes, without looking at her","text":"I walked beside it once. She wouldn't let me ride the step."},{"id":"LH-02-04-A-006","sp":"KIT","dir":"a little sharp","text":"You were seventeen."},{"id":"LH-02-04-A-007","sp":"ELLIS","dir":"quiet","text":"She still let me load it."},{"id":"LH-02-04-A-008","sp":"KIT","dir":"letting that sit","text":"How much did it weigh?"},{"id":"LH-02-04-A-009","sp":"ELLIS","dir":"offering the folded paper","text":"Eighteen sixty. That's the bit that won't leave me alone."}],"journal":""},{"key":"02.04.B","title":"A light left on","kind":"End cinematic","stage":"Ellis leaves. Kit places the ticket beside the sale valuation of the garage.","notes":["Chapter exit: Kit pins the ticket above the workbench frame. Silence, then dawn."],"lines":[{"id":"LH-02-04-B-001","sp":"KIT","dir":"telephone message to Lorna; tired","text":"Generator held under load. If it dies again, call me before you open anything."},{"id":"LH-02-04-B-002","sp":"LORNA","dir":"answering live; amused","text":"You know I picked up?"},{"id":"LH-02-04-B-003","sp":"KIT","dir":"embarrassed","text":"It's late."},{"id":"LH-02-04-B-004","sp":"LORNA","dir":"gentle","text":"You can still go to bed."},{"id":"LH-02-04-B-005","sp":"KIT","dir":"looking at the ticket","text":"Tomorrow I'm taking a look at the weigh station."},{"id":"LH-02-04-B-006","sp":"LORNA","dir":"matter-of-fact","text":"Then take water. That roof's been gone since February."}],"journal":""}]}]},{"n":3,"title":"Weight on the Axle","intro":"Planned gameplay: 240 minutes. The historical ticket records cargo mass after tare subtraction, not an overloaded pickup carrying 1,860 pounds plus passengers.","missions":[{"id":"03.01","title":"Dead Scale","chapter":3,"target":60,"location":"garage to weigh station, 25 road kilometres","unlock":"","objectives":"inspect generator, junction box and scale platform; isolate power; clear debris; identify printer supply requirement.","gameplay":"20 journey, 25 diagnosis, 10 safe clearing, 5 opening.","success":"SCALE_DIAGNOSED. The generator requires a sound belt and connector, obtainable from existing stock or 03.02.","recovery":"no live electrical interaction damages the player during tutorial isolation. Incorrect sequence displays 'isolate supply first'.","choice":"","notes":[],"scenes":[{"key":"03.01.A","title":"The missing roof","kind":"Arrival","stage":"","notes":[],"lines":[{"id":"LH-03-01-A-001","sp":"ELLIS","dir":"looking up","text":"It had a roof when I made the offer."},{"id":"LH-03-01-A-002","sp":"KIT","dir":"squinting","text":"Did you make the offer in January?"},{"id":"LH-03-01-A-003","sp":"ELLIS","dir":"deadpan","text":"Spiritually."},{"id":"LH-03-01-A-004","sp":"KIT","dir":"examining a cable","text":"Don't touch that."},{"id":"LH-03-01-A-005","sp":"ELLIS","dir":"hands up","text":"Already dead."},{"id":"LH-03-01-A-006","sp":"KIT","dir":"firm","text":"Then we can prove it before you put your hand in."},{"id":"LH-03-01-A-007","sp":"ELLIS","dir":"accepting","text":"Isolate. Test. Work."},{"id":"LH-03-01-A-008","sp":"KIT","dir":"approving","text":"You remember something useful."},{"id":"LH-03-01-A-009","sp":"ELLIS","dir":"light","text":"Mostly things she shouted."}],"journal":""},{"key":"03.01.B","title":"The printer","kind":"Interactive diagnosis","stage":"","notes":[],"lines":[{"id":"LH-03-01-B-001","sp":"KIT","dir":"reading model number","text":"You kept the ribbon?"},{"id":"LH-03-01-B-002","sp":"ELLIS","dir":"opening a tin","text":"Kept three."},{"id":"LH-03-01-B-003","sp":"KIT","dir":"surprised","text":"You expected to use it."},{"id":"LH-03-01-B-004","sp":"ELLIS","dir":"finding a reason","text":"Somebody might need to weigh feed."},{"id":"LH-03-01-B-005","sp":"KIT","dir":"not pressing","text":"All right. Somebody needs paper."},{"id":"LH-03-01-B-006","sp":"ELLIS","dir":"pointing at the connector","text":"And that isn't holding another start."},{"id":"LH-03-01-B-007","sp":"KIT","dir":"planning","text":"I'll make a list. You stop treating wire as a structural material."}],"journal":""}]},{"id":"03.02","title":"Paper and Teeth","chapter":3,"target":60,"location":"scrapyard and builders' merchant, 28 road kilometres","unlock":"","objectives":"recover a compatible pulley belt; verify connector rating; exchange a spare part or pay Wes; collect continuous printer paper.","gameplay":"20 scavenge, 20 travel, 10 barter, 10 compatibility and loading.","success":"SCALE_PARTS_READY. Choice PAY_WES or TRADE_WES is financial, without story lock.","recovery":"failed scavenge has a shop alternative funded by a single optional repair at Wes's counter; that repair is performed here, not an undefined side quest.","choice":"","notes":[],"scenes":[{"key":"03.02.A","title":"Wes's paper shelf","kind":"Shop scene","stage":"","notes":[],"lines":[{"id":"LH-03-02-A-001","sp":"WES","dir":"looking at the sample","text":"Haven't sold this since the council bought screens."},{"id":"LH-03-02-A-002","sp":"KIT","dir":"hopeful","text":"Does that mean it's cheap?"},{"id":"LH-03-02-A-003","sp":"WES","dir":"grinning","text":"Means it's buried."},{"id":"LH-03-02-A-004","sp":"KIT","dir":"offering the list","text":"Belt, connector, paper. In that order."},{"id":"LH-03-02-A-005","sp":"WES","dir":"looking at her surname on the invoice","text":"Vale. Right."},{"id":"LH-03-02-A-006","sp":"KIT","dir":"bracing","text":"What's she owe you?"},{"id":"LH-03-02-A-007","sp":"WES","dir":"plain","text":"Nothing."},{"id":"LH-03-02-A-008","sp":"KIT","dir":"surprised","text":"You're sure?"},{"id":"LH-03-02-A-009","sp":"WES","dir":"opening the drawer","text":"I can show you the ledger. I'd prefer you believed me."}],"journal":""},{"key":"03.02.B","title":"If short of money","kind":"Complete alternate transaction","stage":"Trigger: player lacks cash and chooses counter repair. Wes puts a seized vice on the bench; player frees and lubricates its screw.","notes":[],"lines":[{"id":"LH-03-02-B-001","sp":"WES","dir":"demonstrating","text":"It binds halfway. Fix that and we'll call it labour against stock."},{"id":"LH-03-02-B-002","sp":"KIT","dir":"testing","text":"Somebody tightened it with sand in the thread."},{"id":"LH-03-02-B-003","sp":"WES","dir":"dry","text":"A man in a tremendous hurry."},{"id":"LH-03-02-B-004","sp":"KIT","dir":"after repair","text":"That tremendous hurry will need a new handle eventually."},{"id":"LH-03-02-B-005","sp":"WES","dir":"testing smoothly","text":"Put it on my list. Your mother's list used to disappear."},{"id":"LH-03-02-B-006","sp":"KIT","dir":"a clear boundary","text":"Mine's on the invoice. Keep a copy."}],"journal":""}]},{"id":"03.03","title":"Eighteen Sixty","chapter":3,"target":60,"location":"weigh station","unlock":"","objectives":"restore isolated components; calibrate empty platform; weigh the truck; compare carbon and ledger stub; photograph only the relevant entry.","gameplay":"30 repair/calibration, 15 evidence interaction, 15 scenes. Calibration completes through test-weight placement, not simulated waiting.","success":"CARGO_WEIGHT_CONFIRMED and LOT_41_LEAD.","recovery":"a failed calibration identifies imbalance and preserves installed parts. Incorrect ledger selection gets Ellis's factual correction.","choice":"","notes":[],"scenes":[{"key":"03.03.A","title":"Under load","kind":"Interactive test","stage":"","notes":[],"lines":[{"id":"LH-03-03-A-001","sp":"ELLIS","dir":"at controls","text":"Clear?"},{"id":"LH-03-03-A-002","sp":"KIT","dir":"outside platform","text":"Clear. Start it."},{"id":"LH-03-03-A-003","sp":"ELLIS","dir":"as engine catches","text":"No scream. That's an improvement."},{"id":"LH-03-03-A-004","sp":"KIT","dir":"observing","text":"Let the voltage settle. Now the platform."},{"id":"LH-03-03-A-005","sp":"ELLIS","dir":"reading","text":"Zero."},{"id":"LH-03-03-A-006","sp":"KIT","dir":"relieved","text":"Beautiful. Drive it on."},{"id":"LH-03-03-A-007","sp":"ELLIS","dir":"hesitating at the keys","text":"You sure?"},{"id":"LH-03-03-A-008","sp":"KIT","dir":"handing them over","text":"It's a scale, Ellis. I trust you to park."}],"journal":""},{"key":"03.03.B","title":"The subtraction","kind":"Evidence cinematic","stage":"The paper advances. Kit aligns three values with her fingers: gross, tare and net cargo.","notes":[],"lines":[{"id":"LH-03-03-B-001","sp":"KIT","dir":"reading carefully","text":"Truck, fuel, driver deducted. Eighteen sixty in the bed."},{"id":"LH-03-03-B-002","sp":"ELLIS","dir":"low","text":"That's what I said."},{"id":"LH-03-03-B-003","sp":"KIT","dir":"thinking aloud","text":"If it were people, and a few bags—"},{"id":"LH-03-03-B-004","sp":"ELLIS","dir":"interrupting; certainty","text":"It wasn't people."},{"id":"LH-03-03-B-005","sp":"KIT","dir":"stopping","text":"How do you know?"},{"id":"LH-03-03-B-006","sp":"ELLIS","dir":"not theatrical","text":"A truck full of people talks. I walked beside that thing for half a mile. All I heard was dishes."},{"id":"LH-03-03-B-007","sp":"KIT","dir":"finding the next notation","text":"Lot forty-one."},{"id":"LH-03-03-B-008","sp":"ELLIS","dir":"remembering","text":"Sale barn."},{"id":"LH-03-03-B-009","sp":"KIT","dir":"anger beginning","text":"She took it to an auction?"},{"id":"LH-03-03-B-010","sp":"ELLIS","dir":"ashamed","text":"Some of it. I thought there was a system."},{"id":"LH-03-03-B-011","sp":"KIT","dir":"controlled","text":"There was. We need to find out whose."}],"journal":""}]},{"id":"03.04","title":"What You Keep","chapter":3,"target":60,"location":"weigh station to radio station, 22 road kilometres","unlock":"","objectives":"make two evidence copies; secure originals against water; visit Inez; request auction lead; return tools.","gameplay":"20 copying and packing, 25 travel including tool return, 15 interview.","success":"INEZ_CONTACT and FERN_ADDRESS. The player keeps evidence originals in the office archive; vehicle loss never destroys plot evidence.","recovery":"wet copy requires recopying at Inez's station. Originals remain dry in the archive case.","choice":"","notes":[],"scenes":[{"key":"03.04.A","title":"Above Vega Tyre","kind":"Introduction","stage":"","notes":[],"lines":[{"id":"LH-03-04-A-001","sp":"INEZ","dir":"mid-task; welcoming","text":"Mind the step. It behaves like there's another one after it."},{"id":"LH-03-04-A-002","sp":"KIT","dir":"catching herself","text":"There isn't."},{"id":"LH-03-04-A-003","sp":"INEZ","dir":"apologetic smile","text":"That's its trick."},{"id":"LH-03-04-A-004","sp":"KIT","dir":"placing copies down","text":"I'd like the rest of that recording."},{"id":"LH-03-04-A-005","sp":"INEZ","dir":"checking the label","text":"Nineteen seconds is all the county sent me."},{"id":"LH-03-04-A-006","sp":"KIT","dir":"frustrated","text":"Nineteen seconds built a whole fucking story."},{"id":"LH-03-04-A-007","sp":"INEZ","dir":"calm","text":"It did a lot of work. Sit down."}],"journal":""},{"key":"03.04.B","title":"The first boundary","kind":"Interview","stage":"","notes":["Chapter exit: Inez writes an address on the back of a tyre invoice. Kit adds the correction 'trip not yet matched' to her journal."],"lines":[{"id":"LH-03-04-B-001","sp":"INEZ","dir":"listening","text":"Who has seen this?"},{"id":"LH-03-04-B-002","sp":"KIT","dir":"counting","text":"Ellis. Me. Now you."},{"id":"LH-03-04-B-003","sp":"INEZ","dir":"checking","text":"And you want me to say it proves a truck carried belongings."},{"id":"LH-03-04-B-004","sp":"KIT","dir":"insistent","text":"It proves the bed wasn't empty."},{"id":"LH-03-04-B-005","sp":"INEZ","dir":"precise","text":"On this trip. We haven't matched it to the call."},{"id":"LH-03-04-B-006","sp":"KIT","dir":"taking the correction","text":"Right."},{"id":"LH-03-04-B-007","sp":"INEZ","dir":"handing back the original","text":"Fern called that auction. Ask her to read the lot book with you."},{"id":"LH-03-04-B-008","sp":"KIT","dir":"weary","text":"Will she talk?"},{"id":"LH-03-04-B-009","sp":"INEZ","dir":"plain","text":"Ask her. That's usually the first useful thing."}],"journal":""}]}]},{"n":4,"title":"Lot Forty-One","intro":"Planned gameplay: 240 minutes. Returns require ownership discussion. The player never receives an objective to steal from a legitimate buyer.","missions":[{"id":"04.01","title":"The Sale Barn","chapter":4,"target":60,"location":"station, Fern's home and sale barn, 30 road kilometres","unlock":"","objectives":"collect Fern; open the barn; match lot descriptions to photographs; locate the buyer entry and salvage inventory.","gameplay":"25 journey, 20 environmental search, 15 scenes.","success":"AUCTION_CONFIRMED; THREE_RETURN_LEADS. Fern retains her ledger; Kit receives authorized copies.","recovery":"a stuck barn door opens with an available hand lever. Missing photographs are duplicated in Fern's folder.","choice":"","notes":[],"scenes":[{"key":"04.01.A","title":"The call","kind":"Arrival at Fern's","stage":"","notes":[],"lines":[{"id":"LH-04-01-A-001","sp":"FERN","dir":"through an open window","text":"If it's the water bill, I posted it."},{"id":"LH-04-01-A-002","sp":"KIT","dir":"calling back","text":"Kit Vale. Inez sent me."},{"id":"LH-04-01-A-003","sp":"FERN","dir":"a little amused","text":"She knows better than to send the water bill."},{"id":"LH-04-01-A-004","sp":"KIT","dir":"showing the paper","text":"Lot forty-one."},{"id":"LH-04-01-A-005","sp":"FERN","dir":"recognition costs her","text":"I'll get my coat."},{"id":"LH-04-01-A-006","sp":"KIT","dir":"surprised by the speed","text":"You don't need to come."},{"id":"LH-04-01-A-007","sp":"FERN","dir":"firm","text":"It's my book. I'll read it."}],"journal":""},{"key":"04.01.B","title":"Mixed timber","kind":"Barn cinematic","stage":"Fern's working voice briefly fills the empty barn, then falls back into her ordinary register.","notes":[],"lines":[{"id":"LH-04-01-B-001","sp":"FERN","dir":"auction cadence","text":"Forty-one. Mixed household timber. Buyer to collect. Five to start, doors and frames, take them where they stand—"},{"id":"LH-04-01-B-002","sp":"FERN","dir":"stopping; ordinary voice","text":"That's what I said."},{"id":"LH-04-01-B-003","sp":"KIT","dir":"reading the name","text":"Your father bought it."},{"id":"LH-04-01-B-004","sp":"FERN","dir":"plain","text":"Firewood."},{"id":"LH-04-01-B-005","sp":"KIT","dir":"softly","text":"Fuck."},{"id":"LH-04-01-B-006","sp":"FERN","dir":"after a breath","text":"Some doors went before he collected. I never found out who took them."},{"id":"LH-04-01-B-007","sp":"KIT","dir":"checking","text":"You didn't see June?"},{"id":"LH-04-01-B-008","sp":"FERN","dir":"insistent","text":"I didn't see who. Write that too."},{"id":"LH-04-01-B-009","sp":"KIT","dir":"writing","text":"Witness didn't see collection."},{"id":"LH-04-01-B-010","sp":"FERN","dir":"relieved by the accuracy","text":"Thank you."}],"journal":""}]},{"id":"04.02","title":"A Box of Faces","chapter":4,"target":60,"location":"second-hand store and motel, 24 road kilometres","unlock":"","objectives":"identify photo box by three details Alma supplies; negotiate with Wes, who acquired the store stock; return box; request permission to copy one route photograph.","gameplay":"20 travel, 15 object comparison, 10 transaction, 15 scene and journal.","success":"PHOTOS_RETURNED. Choice COPY_ALLOWED or NO_COPY respected by archive system.","recovery":"Wes holds the box after initial visit. If Kit cannot pay, he accepts shelving repair performed in this mission. No photographs are exposed to other testers/players or cloud galleries.","choice":"","notes":[],"scenes":[{"key":"04.02.A","title":"What is in the box","kind":"Store","stage":"","notes":[],"lines":[{"id":"LH-04-02-A-001","sp":"WES","dir":"setting it on felt","text":"I didn't know they were anybody's. Shop closed, stock came over."},{"id":"LH-04-02-A-002","sp":"KIT","dir":"checking photograph corners","text":"Two red corners, one dog with a torn ear. This is it."},{"id":"LH-04-02-A-003","sp":"WES","dir":"uneasy","text":"What do I write on the return?"},{"id":"LH-04-02-A-004","sp":"KIT","dir":"practical","text":"Returned to owner."},{"id":"LH-04-02-A-005","sp":"WES","dir":"turning the receipt","text":"And on the price?"},{"id":"LH-04-02-A-006","sp":"KIT","dir":"if paying","text":"I'll cover your stock cost.","cond":"paying"},{"id":"LH-04-02-A-007","sp":"KIT","dir":"if repairing shelving","text":"You said the shelf needs fixing. Let me do it, then write labour.","cond":"repairing shelving"},{"id":"LH-04-02-A-008","sp":"WES","dir":"accepting","text":"Fair. You can keep the felt around it."}],"journal":""},{"key":"04.02.B","title":"Permission","kind":"Motel room","stage":"","notes":["Player chooses ASK_COPY or LEAVE_PRIVATE:"],"lines":[{"id":"LH-04-02-B-001","sp":"ALMA","dir":"opening the lid","text":"My sister's handwriting. She labelled the dog before she labelled any of us."},{"id":"LH-04-02-B-002","sp":"KIT","dir":"pointing without touching","text":"Could I copy that one? You can see the route behind the house."},{"id":"LH-04-02-B-003","sp":"ALMA","dir":"considering","text":"What will you use it for?"},{"id":"LH-04-02-B-004","sp":"KIT","dir":"honest","text":"To work out where the truck could get through. Inez might need to see it."},{"id":"LH-04-02-B-005","sp":"ALMA","dir":"ASK_COPY","text":"Copy the road. Crop my nephew out. That's the condition.","branch":"ASK_COPY"},{"id":"LH-04-02-B-006","sp":"KIT","dir":"ASK_COPY","text":"Road only. I'll show you before I leave.","branch":"ASK_COPY"},{"id":"LH-04-02-B-007","sp":"KIT","dir":"LEAVE_PRIVATE","text":"I'll mark the bend from memory. You keep these together.","branch":"LEAVE_PRIVATE"},{"id":"LH-04-02-B-008","sp":"ALMA","dir":"LEAVE_PRIVATE; appreciative","text":"Good. Help me find the one where my sister pretends she isn't laughing.","branch":"LEAVE_PRIVATE"},{"id":"LH-04-02-B-009","sp":"ALMA","dir":"finding it; delighted","text":"There. Look at the shoulders. She never fooled anybody."}],"journal":""}]},{"id":"04.03","title":"The Machine in Use","chapter":4,"target":60,"location":"Edie's workshop, parts depot, 26 road kilometres","unlock":"","objectives":"identify sewing machine; hear Edie's purchase history; choose return, repair exchange, or documented present ownership; complete selected work.","gameplay":"20 travel, 20 mechanical restoration or paperwork, 10 choice, 10 scenes.","success":"","recovery":"wrong needle or belt can be swapped from Edie's tray. Negotiation has no intimidation option.","choice":"","notes":["Choice MACHINE_RETURNED: Edie lends it to its original owner's family after Kit repairs an alternative hand machine.","Choice MACHINE_RETAINED: family accepts a payment or no transfer and signs an ownership note; player records that return was declined."],"scenes":[{"key":"04.03.A","title":"The treadle","kind":"Workshop","stage":"","notes":[],"lines":[{"id":"LH-04-03-A-001","sp":"EDIE","dir":"continuing to sew","text":"Don't move the pedal. It'll knock my stitch count off."},{"id":"LH-04-03-A-002","sp":"KIT","dir":"waiting until she stops","text":"Was that bought at Mercy's sale?"},{"id":"LH-04-03-A-003","sp":"EDIE","dir":"guarded","text":"Yes. Paid for it."},{"id":"LH-04-03-A-004","sp":"KIT","dir":"careful","text":"I'm looking for things that came from the houses."},{"id":"LH-04-03-A-005","sp":"EDIE","dir":"hand on the machine","text":"I bought work. It has paid my rent."},{"id":"LH-04-03-A-006","sp":"KIT","dir":"taking that seriously","text":"I'm not putting it on the truck behind your back."},{"id":"LH-04-03-A-007","sp":"EDIE","dir":"a breath","text":"Then you can sit. Mind the pins."}],"journal":""},{"key":"04.03.B","title":"The agreement","kind":"Choice result","stage":"","notes":[],"lines":[{"id":"LH-04-03-B-001","sp":"KIT","dir":"MACHINE_RETURNED","text":"The hand machine holds tension now. She'll take the treadle as a loan until next winter.","branch":"MACHINE_RETURNED"},{"id":"LH-04-03-B-002","sp":"EDIE","dir":"MACHINE_RETURNED","text":"Put the loan in writing. We both deserve to know what's coming back.","branch":"MACHINE_RETURNED"},{"id":"LH-04-03-B-003","sp":"KIT","dir":"MACHINE_RETAINED","text":"They said keep using it. They want a copy of the maker's plate for their record.","branch":"MACHINE_RETAINED"},{"id":"LH-04-03-B-004","sp":"EDIE","dir":"MACHINE_RETAINED; unexpected feeling","text":"I can take a photograph of more than the plate.","branch":"MACHINE_RETAINED"},{"id":"LH-04-03-B-005","sp":"KIT","dir":"MACHINE_RETAINED","text":"Ask them first. They might like that.","branch":"MACHINE_RETAINED"},{"id":"LH-04-03-B-006","sp":"EDIE","dir":"reflective","text":"I used to collect tickets. All the places I thought I'd go."},{"id":"LH-04-03-B-007","sp":"KIT","dir":"curious","text":"Still got them?"},{"id":"LH-04-03-B-008","sp":"EDIE","dir":"a smile","text":"Better organized than the places."}],"journal":""}]},{"id":"04.04","title":"The Locked Room","chapter":4,"target":60,"location":"garage and nearby storage annex","unlock":"","objectives":"find storage key using June's tagged key board; inventory six crates; match returns to owners; make a safe delivery plan.","gameplay":"20 storage exploration, 20 sorting and securing, 10 route planning, 10 scenes.","success":"RETURN_ROUTE_PLANNED; CLEARANCE_FORM_FOUND. This is the first signed form, not yet its complete official attachment.","recovery":"damaged labels can be reconstructed from June's ledger. The player can ask Ellis to read her abbreviations.","choice":"","notes":[],"scenes":[{"key":"04.04.A","title":"Unfinished deliveries","kind":"Reveal cinematic","stage":"A door opens on carefully stored possessions. Kit reads labels. June's abbreviated addresses are accurate.","notes":[],"lines":[{"id":"LH-04-04-A-001","sp":"KIT","dir":"quiet disbelief","text":"She packed them."},{"id":"LH-04-04-A-002","sp":"ELLIS","dir":"looking at a crate","text":"That one's Mrs. Torres. She moved three times."},{"id":"LH-04-04-A-003","sp":"KIT","dir":"anger rising","text":"Then cross out the address. Write another one. Put the fucking box on the truck."},{"id":"LH-04-04-A-004","sp":"ELLIS","dir":"not defending","text":"I know."},{"id":"LH-04-04-A-005","sp":"KIT","dir":"turning","text":"Did you come in here?"},{"id":"LH-04-04-A-006","sp":"ELLIS","dir":"ashamed","text":"When she asked for something."},{"id":"LH-04-04-A-007","sp":"KIT","dir":"a hard question","text":"Did you ask what the rest was?"},{"id":"LH-04-04-A-008","sp":"ELLIS","dir":"after a pause","text":"No."},{"id":"LH-04-04-A-009","sp":"KIT","dir":"wounded","text":"Neither did I."}],"journal":""},{"key":"04.04.B","title":"The signature","kind":"End","stage":"Kit finds the clearance contractor form beneath wrapping paper. The attachment is missing.","notes":["Chapter exit: Player chooses the first two delivery crates. These selections determine the order of 05.01 destinations, never access to essential evidence."],"lines":[{"id":"LH-04-04-B-001","sp":"KIT","dir":"reading","text":"Collection complete. Site cleared as instructed."},{"id":"LH-04-04-B-002","sp":"ELLIS","dir":"trying to see","text":"Her signature?"},{"id":"LH-04-04-B-003","sp":"KIT","dir":"showing it","text":"Every letter."},{"id":"LH-04-04-B-004","sp":"ELLIS","dir":"cautious","text":"We don't know what was attached."},{"id":"LH-04-04-B-005","sp":"KIT","dir":"controlled","text":"Then that's what we find."},{"id":"LH-04-04-B-006","sp":"ELLIS","dir":"offering","text":"And the boxes?"},{"id":"LH-04-04-B-007","sp":"KIT","dir":"deciding","text":"We deliver them. Finding out is going to take longer than giving something back."}],"journal":""}]}]},{"n":5,"title":"The Old Detour","intro":"Planned gameplay: 300 minutes. The route reaches more remote settlements. Sera's checkpoint is authored; incidental encounters obey normal game rules.","missions":[{"id":"05.01","title":"Addresses That Moved","chapter":5,"target":75,"location":"garage, Torres home and camp, 38 road kilometres","unlock":"","objectives":"return cookware to Rosa Torres; locate the current owner of a lamp; deliver envelopes and flour; record actual recipients.","gameplay":"30 multi-stop driving, 15 cargo handling, 15 searching current addresses, 15 dialogue.","success":"TORRES_CONTACT; SUPPLIES_DELIVERED. Missing supplies set SUPPLIES_SHARED and change later thank-you lines.","recovery":"post office spare envelopes and Lorna's reserve flour are explicit map stops, unlocked free after one lost shipment. Help is limited per mission to avoid resource farming.","choice":"","notes":[],"scenes":[{"key":"05.01.A","title":"The wrong gate","kind":"Rosa's yard","stage":"","notes":[],"lines":[{"id":"LH-05-01-A-001","sp":"ROSA","dir":"watchful","text":"Deliveries go to the camp."},{"id":"LH-05-01-A-002","sp":"KIT","dir":"holding the label","text":"I've got a crate for Rosa Torres."},{"id":"LH-05-01-A-003","sp":"ROSA","dir":"recognizing the handwriting","text":"Put it down before you tell me who sent you."},{"id":"LH-05-01-A-004","sp":"KIT","dir":"carefully","text":"June Vale died. I'm sorting what she left."},{"id":"LH-05-01-A-005","sp":"ROSA","dir":"absorbing that","text":"All right. Put it in the shade."},{"id":"LH-05-01-A-006","sp":"KIT","dir":"after setting it down","text":"I'm sorry it took this long."},{"id":"LH-05-01-A-007","sp":"ROSA","dir":"opening a familiar lid","text":"You didn't keep it twelve years."},{"id":"LH-05-01-A-008","sp":"KIT","dir":"quiet","text":"It's still late."},{"id":"LH-05-01-A-009","sp":"ROSA","dir":"plain","text":"Yes. It is."}],"journal":""},{"key":"05.01.B","title":"What can be shared","kind":"Camp handover","stage":"","notes":[],"lines":[{"id":"LH-05-01-B-001","sp":"MANNY","dir":"if full supplies","text":"Flour, envelopes, lamp fuel. Somebody made a proper list.","cond":"full supplies"},{"id":"LH-05-01-B-002","sp":"KIT","dir":"if full supplies","text":"Alma made the list. I'm only trying to arrive with it intact.","cond":"full supplies"},{"id":"LH-05-01-B-003","sp":"MANNY","dir":"if supplies lost","text":"We've enough flour for today. Split it between the two kitchens.","cond":"supplies lost"},{"id":"LH-05-01-B-004","sp":"KIT","dir":"if supplies lost; frustrated","text":"I should have checked that strap.","cond":"supplies lost"},{"id":"LH-05-01-B-005","sp":"MANNY","dir":"if supplies lost","text":"Check the next one. We've still got supper.","cond":"supplies lost"},{"id":"LH-05-01-B-006","sp":"ROSA","dir":"to Kit","text":"Come back when you've got time to sit. My daughter used to ride with your mother."},{"id":"LH-05-01-B-007","sp":"KIT","dir":"attentive","text":"I will. Can I bring the box lid? The name's fading."},{"id":"LH-05-01-B-008","sp":"ROSA","dir":"agreeing","text":"Bring a pencil. I'll spell the new address myself."}],"journal":""}]},{"id":"05.02","title":"Forty at the Line","chapter":5,"target":75,"location":"culvert checkpoint and fuel depot, 35 road kilometres","unlock":"","objectives":"approach warning zone; hear terms; choose toll, material trade, retreat/bypass, or force crossing; reach the depot.","gameplay":"25 route survey and driving, 15 negotiation, 25 selected trade/bypass/pursuit gameplay, 10 scenes.","success":"","recovery":"capture uses nonlethal loss in campaign difficulty; lethal combat or crashes reload latest encounter checkpoint. If Sera is incapacitated, later essential contact is written correspondence delivered by Len.","choice":"","notes":["Branches: PAY and TRADE set SERA_WORKING_CONTACT. RETREAT uses marked 12-kilometre bypass. RAM uses ordinary pursuit until all active pursuit vehicles physically disabled, then ESCAPED_CHECKPOINT. No objective requires killing anyone."],"scenes":[{"key":"05.02.A","title":"The toll","kind":"Stopped at the line","stage":"","notes":[],"lines":[{"id":"LH-05-02-A-001","sp":"SERA","dir":"clear warning","text":"Stop before the barrels. Engine off if you're staying."},{"id":"LH-05-02-A-002","sp":"KIT","dir":"through window","text":"I'm passing through."},{"id":"LH-05-02-A-003","sp":"SERA","dir":"businesslike","text":"Forty dollars."},{"id":"LH-05-02-A-004","sp":"KIT","dir":"looking at the crew","text":"How much of that buys road?"},{"id":"LH-05-02-A-005","sp":"LEN","dir":"from the culvert","text":"Pipe cost seventy-eight."},{"id":"LH-05-02-A-006","sp":"SERA","dir":"a warning to Len","text":"I'm handling it."},{"id":"LH-05-02-A-007","sp":"KIT","dir":"seeing an opening","text":"I've got a truck. Materials go in the bed."},{"id":"LH-05-02-A-008","sp":"SERA","dir":"interested despite herself","text":"Diesel tomorrow. Sealed can. We measure it here."},{"id":"LH-05-02-A-009","sp":"KIT","dir":"weighing it","text":"Or forty now."},{"id":"LH-05-02-A-010","sp":"SERA","dir":"plain","text":"Or turn around."}],"journal":""},{"key":"05.02.B","title":"Selected response","kind":"At player choice","stage":"","notes":[],"lines":[{"id":"LH-05-02-B-001","sp":"KIT","dir":"PAY","text":"Forty. Write it down with the truck number.","branch":"PAY"},{"id":"LH-05-02-B-002","sp":"SERA","dir":"PAY","text":"Receipt's on the crate. Keep it for the return.","branch":"PAY"},{"id":"LH-05-02-B-003","sp":"KIT","dir":"TRADE","text":"I'll bring twenty litres. Open the road when I return with it.","branch":"TRADE"},{"id":"LH-05-02-B-004","sp":"SERA","dir":"TRADE","text":"Keep it sealed. Len checks it.","branch":"TRADE"},{"id":"LH-05-02-B-005","sp":"KIT","dir":"RETREAT","text":"I'm taking the long way.","branch":"RETREAT"},{"id":"LH-05-02-B-006","sp":"SERA","dir":"RETREAT","text":"Past the blue tank. Keep clear of the washed shoulder.","branch":"RETREAT"},{"id":"LH-05-02-B-007","sp":"KIT","dir":"RAM; to herself as driving resumes","text":"Seat belt. Windows up. Fuck this.","branch":"RAM"},{"id":"LH-05-02-B-008","sp":"SERA","dir":"RAM; shouted to crew","text":"They're through. Get in!","branch":"RAM"},{"id":"LH-05-02-B-009","sp":"LEN","dir":"RAM; urgent","text":"Leave the man in the ditch alone. He's working!","branch":"RAM"}],"journal":""},{"key":"05.02.C","title":"At the safe depot","kind":"Branch close","stage":"","notes":[],"lines":[{"id":"LH-05-02-C-001","sp":"KIT","dir":"PAY or TRADE; radio","text":"I got through. She wants receipts more than apologies."},{"id":"LH-05-02-C-002","sp":"ELLIS","dir":"PAY or TRADE; radio","text":"Useful. Your mother tried the opposite."},{"id":"LH-05-02-C-003","sp":"KIT","dir":"RETREAT; radio","text":"Bypass is open. Add twelve kilometres and don't use it after rain.","branch":"RETREAT"},{"id":"LH-05-02-C-004","sp":"ELLIS","dir":"RETREAT; radio","text":"Marked. I'll tell Alma before she sends somebody.","branch":"RETREAT"},{"id":"LH-05-02-C-005","sp":"KIT","dir":"ESCAPED_CHECKPOINT; breathing hard","text":"I'm stopped. I'm checking the wheels. Then I'm going to be very fucking angry.","branch":"ESCAPED_CHECKPOINT"},{"id":"LH-05-02-C-006","sp":"ELLIS","dir":"ESCAPED_CHECKPOINT; steady","text":"Take your time. Tell me whether you can see daylight through the radiator.","branch":"ESCAPED_CHECKPOINT"},{"id":"LH-05-02-C-007","sp":"KIT","dir":"CAPTURE_RECOVERY; drained","text":"They took the cash. Truck's moving.","branch":"CAPTURE_RECOVERY"},{"id":"LH-05-02-C-008","sp":"ELLIS","dir":"CAPTURE_RECOVERY","text":"Get to the depot. We can argue about the cash in the shade.","branch":"CAPTURE_RECOVERY"}],"journal":""}]},{"id":"05.03","title":"The Pipe","chapter":5,"target":75,"location":"depot, checkpoint/bypass and garage, 36 road kilometres","unlock":"","objectives":"obtain the quoted pipe invoice; deliver diesel if promised; inspect culvert from public access; survey a safe future passenger route.","gameplay":"25 material transport, 20 physical road inspection, 15 route survey, 15 conversation.","success":"DETOUR_ASSESSED. If hostile checkpoint, Len meets at the bypass lay-by; essential road information survives all crew outcomes.","recovery":"player can fulfill trade through Len after Sera injury. A missed promise is resolved by later delivery, with changed trust but no campaign lock.","choice":"","notes":[],"scenes":[{"key":"05.03.A","title":"The invoice","kind":"Civil version","stage":"","notes":[],"lines":[{"id":"LH-05-03-A-001","sp":"LEN","dir":"showing damage","text":"Water goes under it, if people stop throwing rubbish in it."},{"id":"LH-05-03-A-002","sp":"KIT","dir":"looking at the pipe","text":"Seventy-eight?"},{"id":"LH-05-03-A-003","sp":"LEN","dir":"handing invoice","text":"Before the transport."},{"id":"LH-05-03-A-004","sp":"SERA","dir":"if civil; measured","text":"I got the transport.","cond":"civil"},{"id":"LH-05-03-A-005","sp":"KIT","dir":"if civil","text":"Then put both on the board.","cond":"civil"},{"id":"LH-05-03-A-006","sp":"SERA","dir":"if civil; irritated","text":"You auditing us?","cond":"civil"},{"id":"LH-05-03-A-007","sp":"KIT","dir":"if civil","text":"Thinking about a passenger route. I need to know what using it costs.","cond":"civil"}],"journal":""},{"key":"05.03.B","title":"The invoice","kind":"Hostile or Sera unavailable version","stage":"","notes":[],"lines":[{"id":"LH-05-03-B-001","sp":"LEN","dir":"at bypass lay-by","text":"I came on foot. Nobody's following me."},{"id":"LH-05-03-B-002","sp":"KIT","dir":"guarded","text":"Why?"},{"id":"LH-05-03-B-003","sp":"LEN","dir":"holding the invoice","text":"You asked what the pipe cost. Seventy-eight."},{"id":"LH-05-03-B-004","sp":"KIT","dir":"looking toward checkpoint","text":"And the rest?"},{"id":"LH-05-03-B-005","sp":"LEN","dir":"tired","text":"Ask the people counting it. I can tell you where the shoulder's sound."},{"id":"LH-05-03-B-006","sp":"KIT","dir":"after a pause","text":"Show me."},{"id":"LH-05-03-B-007","sp":"LEN","dir":"pointing at survey mark","text":"Keep a heavy vehicle inside this line."},{"id":"LH-05-03-B-008","sp":"KIT","dir":"recording it","text":"That's the first instruction I've had here that won't change with my wallet."}],"journal":""},{"key":"05.03.C","title":"A possible agreement","kind":"Optional civil branch","stage":"","notes":["Hostile branch instead records BYPASS_REQUIRED without spoken negotiation."],"lines":[{"id":"LH-05-03-C-001","sp":"SERA","dir":"reading Kit's survey","text":"Regular trips?"},{"id":"LH-05-03-C-002","sp":"KIT","dir":"careful","text":"Maybe. No promises yet."},{"id":"LH-05-03-C-003","sp":"SERA","dir":"calculating","text":"We'd need times. Crew moves the truck for the grader."},{"id":"LH-05-03-C-004","sp":"KIT","dir":"firm","text":"Times work both ways. No new charge at the window."},{"id":"LH-05-03-C-005","sp":"SERA","dir":"after considering","text":"Bring a timetable when you've got one."},{"id":"LH-05-03-C-006","sp":"KIT","dir":"warning","text":"I'll bring something you can sign."}],"journal":""}]},{"id":"05.04","title":"The Family at the Edge","chapter":5,"target":75,"location":"Torres home and garage, 32 road kilometres","unlock":"","objectives":"return lid; speak to Rosa and her adult son Mateo; identify last evacuation day; ask permission for a future interview.","gameplay":"25 journey, 15 return and household help, 20 conversation, 15 journaling and camp preparation.","success":"LAST_FAMILY_IDENTIFIED. MATEO_CONSENT and ROSA_CONSENT tracked independently.","recovery":"if player presses after refusal, witnesses stop the interview; Kit may return after delivering a written explanation in 08.01. Mandatory chronology comes from records, not coerced testimony.","choice":"","notes":[],"scenes":[{"key":"05.04.A","title":"The good skillet","kind":"Kitchen scene","stage":"","notes":[],"lines":[{"id":"LH-05-04-A-001","sp":"ROSA","dir":"lifting a skillet","text":"Your mother brought this. Went back for it after we were out."},{"id":"LH-05-04-A-002","sp":"KIT","dir":"carefully","text":"You were still at Mercy that afternoon?"},{"id":"LH-05-04-A-003","sp":"ROSA","dir":"watching her","text":"We went back for the dog. Mateo knew where he'd hide."},{"id":"LH-05-04-A-004","sp":"MATEO","dir":"correcting his mother's recollection","text":"I knew the yard. We found him under the tank."},{"id":"LH-05-04-A-005","sp":"KIT","dir":"listening","text":"June was coming for you?"},{"id":"LH-05-04-A-006","sp":"ROSA","dir":"plain","text":"She said stay by the road. We did."},{"id":"LH-05-04-A-007","sp":"MATEO","dir":"contained anger","text":"Nico arrived. That's who I remember opening a door."},{"id":"LH-05-04-A-008","sp":"KIT","dir":"without defending June","text":"May I write that?"},{"id":"LH-05-04-A-009","sp":"ROSA","dir":"a condition","text":"Our names stay here until we decide otherwise."}],"journal":""},{"key":"05.04.B","title":"Outside","kind":"End cinematic","stage":"Mateo follows Kit to the gate.","notes":["Chapter exit: Kit writes 'Nico opened the door' below June's clearance form."],"lines":[{"id":"LH-05-04-B-001","sp":"MATEO","dir":"checking her intention","text":"Are you trying to get her forgiven?"},{"id":"LH-05-04-B-002","sp":"KIT","dir":"honest uncertainty","text":"I don't know what I'm trying to get yet."},{"id":"LH-05-04-B-003","sp":"MATEO","dir":"direct","text":"Figure that out before you come back."},{"id":"LH-05-04-B-004","sp":"KIT","dir":"taking it","text":"Fair."},{"id":"LH-05-04-B-005","sp":"MATEO","dir":"softening a fraction","text":"The dog lived another six years."},{"id":"LH-05-04-B-006","sp":"KIT","dir":"a small, sad smile","text":"What was his name?"},{"id":"LH-05-04-B-007","sp":"MATEO","dir":"unexpected humour","text":"Bishop. Absolute bastard to get in a car."}],"journal":""}]}]},{"n":6,"title":"What She Signed","intro":"Planned gameplay: 240 minutes. Calder is reached on an authored spur. Private documents remain in a local campaign archive, not public collectible galleries.","missions":[{"id":"06.01","title":"The Counter","chapter":6,"target":60,"location":"garage to Calder records office, 30 road kilometres","unlock":"","objectives":"bring estate identification; request contractor file; distinguish public documents from restricted statements; collect permission forms.","gameplay":"25 travel, 15 document interaction, 10 office navigation, 10 scenes.","success":"RECORDS_REQUEST_OPEN. Missing identification can be faxed from garage through Inez without a repeat full journey.","recovery":"office always offers an appointment window. Arriving after hours advances to morning at a nearby rest stop with no forced real-time wait.","choice":"","notes":[],"scenes":[{"key":"06.01.A","title":"What is attached","kind":"Records counter","stage":"","notes":[],"lines":[{"id":"LH-06-01-A-001","sp":"MARA","dir":"professional","text":"Contractor or resident file?"},{"id":"LH-06-01-A-002","sp":"KIT","dir":"offering the form","text":"June Vale. I'm handling her estate."},{"id":"LH-06-01-A-003","sp":"MARA","dir":"reading","text":"This gives you access to her contract. The attachment includes other households."},{"id":"LH-06-01-A-004","sp":"KIT","dir":"impatient","text":"It's attached to her signature."},{"id":"LH-06-01-A-005","sp":"MARA","dir":"even","text":"And to their addresses, medical details and statements from children."},{"id":"LH-06-01-A-006","sp":"KIT","dir":"backing off slightly","text":"I don't want those on the radio."},{"id":"LH-06-01-A-007","sp":"MARA","dir":"offering a pen","text":"Good. List the documents you need. We'll mark the permissions."},{"id":"LH-06-01-A-008","sp":"KIT","dir":"sitting","text":"How many trips is this going to take?"},{"id":"LH-06-01-A-009","sp":"MARA","dir":"practical","text":"Fewer if we make the list properly."}],"journal":""},{"key":"06.01.B","title":"The appointment","kind":"Exit","stage":"","notes":[],"lines":[{"id":"LH-06-01-B-001","sp":"MARA","dir":"giving receipt","text":"Request number at the top. Keep it when you call."},{"id":"LH-06-01-B-002","sp":"KIT","dir":"checking the total","text":"No copying fee?"},{"id":"LH-06-01-B-003","sp":"MARA","dir":"plain","text":"Correction requests get the first set free."},{"id":"LH-06-01-B-004","sp":"KIT","dir":"surprised","text":"You think it needs correcting?"},{"id":"LH-06-01-B-005","sp":"MARA","dir":"precise","text":"I think you asked. That's enough to open the process."},{"id":"LH-06-01-B-006","sp":"KIT","dir":"sincere","text":"Thank you."},{"id":"LH-06-01-B-007","sp":"MARA","dir":"returning to work","text":"Bring names with permission. Leave guesses out."}],"journal":""}]},{"id":"06.02","title":"Permission to Ask","chapter":6,"target":60,"location":"Calder, motel and radio station, 26 road kilometres","unlock":"","objectives":"obtain Alma's permission; ask Ellis about signing his account; consult Nico on wording; arrange secure document transfer.","gameplay":"20 driving, 25 witness discussions, 10 paperwork, 5 handover.","success":"PERMISSIONS_LOGGED.","recovery":"unclear wording can be revised during the meeting. No consent obtained while a character is injured, asleep, or in combat is accepted.","choice":"ASK_PUBLIC or ASK_PRIVATE wording leads to corresponding consent forms. A refusal reduces publishable material, never blocks the primary file correction.","notes":[],"scenes":[{"key":"06.02.A","title":"The form","kind":"Alma's room","stage":"","notes":[],"lines":[{"id":"LH-06-02-A-001","sp":"ALMA","dir":"reading aloud","text":"May be reproduced. That's a large little sentence."},{"id":"LH-06-02-A-002","sp":"KIT","dir":"explaining","text":"It covers a radio extract and the correction file."},{"id":"LH-06-02-A-003","sp":"ALMA","dir":"asking","text":"Does it cover somebody else uploading it?"},{"id":"LH-06-02-A-004","sp":"KIT","dir":"honest","text":"I can't promise nobody will."},{"id":"LH-06-02-A-005","sp":"ALMA","dir":"deciding","text":"Then my name can go in the correction. My bedroom address stays off everything."},{"id":"LH-06-02-A-006","sp":"KIT","dir":"writing the limit","text":"I'll strike it here and initial it."},{"id":"LH-06-02-A-007","sp":"ALMA","dir":"watching","text":"Show me my copy when you're done."},{"id":"LH-06-02-A-008","sp":"KIT","dir":"steady","text":"Before I take the other one."}],"journal":""},{"key":"06.02.B","title":"Ellis's account","kind":"Garage","stage":"","notes":[],"lines":[{"id":"LH-06-02-B-001","sp":"ELLIS","dir":"defensive","text":"I'll sign. Whatever says I loaded it."},{"id":"LH-06-02-B-002","sp":"KIT","dir":"careful","text":"Read it first."},{"id":"LH-06-02-B-003","sp":"ELLIS","dir":"frustrated","text":"I was there."},{"id":"LH-06-02-B-004","sp":"KIT","dir":"firm","text":"Then you should care whether it says you were seventeen or twenty."},{"id":"LH-06-02-B-005","sp":"ELLIS","dir":"looking down","text":"Seventeen."},{"id":"LH-06-02-B-006","sp":"KIT","dir":"noticing fear","text":"You can take it home."},{"id":"LH-06-02-B-007","sp":"ELLIS","dir":"quiet","text":"If I take it home, I can put it in a drawer again."},{"id":"LH-06-02-B-008","sp":"KIT","dir":"offering a middle ground","text":"Read it here. I'll work in the yard."}],"journal":""},{"key":"06.02.C","title":"Nico's advice","kind":"Telephone","stage":"","notes":[],"lines":[{"id":"LH-06-02-C-001","sp":"NICO","dir":"telephone; precise","text":"Ask who can change their mind, and until when."},{"id":"LH-06-02-C-002","sp":"KIT","dir":"writing","text":"Until publication."},{"id":"LH-06-02-C-003","sp":"NICO","dir":"confirming","text":"Put the date beside it. If she withdraws, don't make her explain why."},{"id":"LH-06-02-C-004","sp":"KIT","dir":"tired","text":"You're very good at finding work I haven't done."},{"id":"LH-06-02-C-005","sp":"NICO","dir":"gently","text":"That's why you called."}],"journal":""}]},{"id":"06.03","title":"The Attachment","chapter":6,"target":60,"location":"records archive and Calder garage","unlock":"","objectives":"collect authorized file; compare five timestamps; verify vehicle description; repair a tyre before return; mark contradictions without resolving them prematurely.","gameplay":"20 evidence assembly, 20 maintenance, 10 local travel, 10 scenes.","success":"CLEARANCE_ATTACHMENT_FOUND; OWEN_INTERVIEW_UNLOCKED.","recovery":"comparison UI retains correct pairings; wrong matches produce a source citation. A failed repair has a shop option paid from the records travel allowance.","choice":"","notes":[],"scenes":[{"key":"06.03.A","title":"Vacancy confirmed","kind":"Archive room","stage":"","notes":[],"lines":[{"id":"LH-06-03-A-001","sp":"MARA","dir":"placing pages in order","text":"Contract. Radio transcription. Clearance instruction. Completion."},{"id":"LH-06-03-A-002","sp":"KIT","dir":"stopping at transcription","text":"They wrote population zero."},{"id":"LH-06-03-A-003","sp":"MARA","dir":"precise","text":"The transcript operator wrote it. Pike approved the attached instruction."},{"id":"LH-06-03-A-004","sp":"KIT","dir":"finding June's signature","text":"And she signed this after."},{"id":"LH-06-03-A-005","sp":"MARA","dir":"careful","text":"Yes."},{"id":"LH-06-03-A-006","sp":"KIT","dir":"unable to soften it","text":"Shit."},{"id":"LH-06-03-A-007","sp":"MARA","dir":"giving her time","text":"There's water outside the room."},{"id":"LH-06-03-A-008","sp":"KIT","dir":"staying","text":"No. Put the dates beside each other. I want to see how long she had."}],"journal":""},{"key":"06.03.B","title":"At the tyre bay","kind":"Processing while working","stage":"","notes":[],"lines":[{"id":"LH-06-03-B-001","sp":"NICO","dir":"meeting her with coffee","text":"Mara called. Said you might need somebody to read it with."},{"id":"LH-06-03-B-002","sp":"KIT","dir":"holding a wrench too tightly","text":"Every time I find a page, I think the next one's going to let her off."},{"id":"LH-06-03-B-003","sp":"NICO","dir":"plain","text":"This one doesn't."},{"id":"LH-06-03-B-004","sp":"KIT","dir":"angry at herself","text":"I know how to read, Nico."},{"id":"LH-06-03-B-005","sp":"NICO","dir":"not escalating","text":"I know."},{"id":"LH-06-03-B-006","sp":"KIT","dir":"after working the nut free","text":"Sorry."},{"id":"LH-06-03-B-007","sp":"NICO","dir":"offering coffee","text":"Take this before you burn a hole in the wheel."}],"journal":""}]},{"id":"06.04","title":"Owen's Account","chapter":6,"target":60,"location":"Calder outskirts and garage, 28 road kilometres","unlock":"","objectives":"interview Owen at his workshop; ask all three factual questions; mark his claims; return complete file to secure storage.","gameplay":"20 travel, 20 workshop navigation and contextual inspection, 15 interview, 5 closing.","success":"OWEN_ACCOUNT_1. His claim 'June confirmed vacancy' is a claim, not final truth.","recovery":"if conversation ends early, Inez obtains written responses to the same questions the next morning.","choice":"calm or confrontational Kit wording changes Owen's tone. Essential answers remain recorded.","notes":[],"scenes":[{"key":"06.04.A","title":"The supervisor","kind":"Interview","stage":"","notes":[],"lines":[{"id":"LH-06-04-A-001","sp":"OWEN","dir":"controlled courtesy","text":"I knew your mother. She got a lot of people through a difficult week."},{"id":"LH-06-04-A-002","sp":"KIT","dir":"CALM","text":"I'm trying to match the call to the clearance.","branch":"CALM"},{"id":"LH-06-04-A-003","sp":"KIT","dir":"CONFRONTATIONAL","text":"Then explain why this says the town was empty when it wasn't.","branch":"CONFRONTATIONAL"},{"id":"LH-06-04-A-004","sp":"OWEN","dir":"composed","text":"We received a vacancy confirmation. I authorized the contractor to proceed."},{"id":"LH-06-04-A-005","sp":"KIT","dir":"specific","text":"Did you speak to anyone on the site?"},{"id":"LH-06-04-A-006","sp":"OWEN","dir":"choosing words","text":"I used the chain of reports available."},{"id":"LH-06-04-A-007","sp":"KIT","dir":"pressing","text":"That's a no."},{"id":"LH-06-04-A-008","sp":"OWEN","dir":"cooling","text":"That's the procedure we had."}],"journal":""},{"key":"06.04.B","title":"The third question","kind":"Interview continuation","stage":"","notes":[],"lines":[{"id":"LH-06-04-B-001","sp":"KIT","dir":"showing the signature","text":"She signed completion after the demolition started."},{"id":"LH-06-04-B-002","sp":"OWEN","dir":"nodding","text":"Her truck was recovered that evening. Paperwork came through afterward."},{"id":"LH-06-04-B-003","sp":"KIT","dir":"a new detail","text":"Recovered?"},{"id":"LH-06-04-B-004","sp":"OWEN","dir":"matter-of-fact","text":"Service road gave way. Ask your mechanic about the chassis repair."},{"id":"LH-06-04-B-005","sp":"KIT","dir":"checking herself","text":"Last question. Who checked the corrected report?"},{"id":"LH-06-04-B-006","sp":"OWEN","dir":"guarded","text":"There was no corrected vacancy confirmation in the file I approved."},{"id":"LH-06-04-B-007","sp":"KIT","dir":"leaving","text":"I'm going to find out why."},{"id":"LH-06-04-B-008","sp":"OWEN","dir":"at the door","text":"You have twelve years and a quiet room. Remember what we had."},{"id":"LH-06-04-B-009","sp":"KIT","dir":"without shouting","text":"I can remember that and still ask."}],"journal":""},{"key":"06.04.C","title":"Nineteen seconds","kind":"Chapter end","stage":"Kit listens to the short public recording at the garage. Let the silence after it remain unscored.","notes":["Chapter exit: The journal now lists 'relay recording' as the missing evidence, with Inez as the lead."],"lines":[{"id":"LH-06-04-C-001","sp":"JUNE","dir":"archival; same source take as 02.03","text":"Mercy empty. Returning to depot."},{"id":"LH-06-04-C-002","sp":"KIT","dir":"to the empty room","text":"What the hell did you think you were signing?"}],"journal":""}]}]},{"n":7,"title":"Eleven Minutes","intro":"Planned gameplay: 300 minutes. This chapter fixes the historical chronology. All archive dates are relative to clearance day. The long-trip gameplay uses the remote relay route, not repeated collection of the same part.","missions":[{"id":"07.01","title":"Above the Weather","chapter":7,"target":75,"location":"radio station, supply depot and relay foothills, 40 road kilometres","unlock":"","objectives":"ask Inez about the original receiver; pack water, belt, connector and spare fuel; record route bearings; reach the relay rest point.","gameplay":"20 preparation with meaningful cargo space decisions, 35 remote driving, 10 road survey, 10 scenes.","success":"RELAY_APPROACH. Night arrival offers safe rest; story recording cannot become inaccessible through time of day.","recovery":"an abandoned maintenance locker contains emergency water and one compatible connector. After a breakdown, Ellis can deliver one rescue supply pack in return for a recorded garage debt.","choice":"","notes":[],"scenes":[{"key":"07.01.A","title":"Two microphones","kind":"Radio station briefing","stage":"","notes":[],"lines":[{"id":"LH-07-01-A-001","sp":"INEZ","dir":"showing a diagram","text":"County recorder was at the depot. The relay kept its own logging tape."},{"id":"LH-07-01-A-002","sp":"KIT","dir":"sceptical","text":"And nobody checked it?"},{"id":"LH-07-01-A-003","sp":"INEZ","dir":"careful","text":"I haven't found a record of anyone requesting it."},{"id":"LH-07-01-A-004","sp":"KIT","dir":"understanding the distinction","text":"Doesn't mean they didn't."},{"id":"LH-07-01-A-005","sp":"INEZ","dir":"approving","text":"Exactly."},{"id":"LH-07-01-A-006","sp":"ELLIS","dir":"examining the road drawing","text":"Last section needs low gear. Stop below the mast if the shoulder's wet."},{"id":"LH-07-01-A-007","sp":"KIT","dir":"checking her list","text":"Water, fuel, belt, paper."},{"id":"LH-07-01-A-008","sp":"INEZ","dir":"adding one item","text":"A way to bring it back dry."}],"journal":""},{"key":"07.01.B","title":"The last services","kind":"Departure","stage":"","notes":[],"lines":[{"id":"LH-07-01-B-001","sp":"LORNA","dir":"handing a food tin","text":"Bread goes on top. You put oil on it, you eat oily bread."},{"id":"LH-07-01-B-002","sp":"KIT","dir":"touched, disguising it","text":"That your official storage advice?"},{"id":"LH-07-01-B-003","sp":"LORNA","dir":"matter-of-fact","text":"It's the advice that gets ignored most."},{"id":"LH-07-01-B-004","sp":"ELLIS","dir":"checking the jack","text":"Call at the blue tank. If I don't hear you, I'll call you."},{"id":"LH-07-01-B-005","sp":"KIT","dir":"a promise","text":"Blue tank. Before the climb."},{"id":"LH-07-01-B-006","sp":"INEZ","dir":"quietly","text":"If the road goes, leave the tape. Ring me."},{"id":"LH-07-01-B-007","sp":"KIT","dir":"meeting her eyes","text":"Understood."}],"journal":""}]},{"id":"07.02","title":"Power to the Relay","chapter":7,"target":75,"location":"relay station","unlock":"","objectives":"survey footing; isolate generator; repair feed; dry and clean tape bay; test playback on sacrificial calibration reel.","gameplay":"15 approach and equipment carrying, 35 repair, 15 cleaning and test, 10 scenes.","success":"RELAY_POWERED. The calibration reel is replaceable; archival material stays locked until correct playback is verified.","recovery":"damaged test tape costs time and a fresh test section. Player is told to reduce tension and may request Inez's remote guidance.","choice":"","notes":[],"scenes":[{"key":"07.02.A","title":"The shack","kind":"Arrival","stage":"","notes":[],"lines":[{"id":"LH-07-02-A-001","sp":"KIT","dir":"radio; breath from carrying gear","text":"At the relay. Door's hanging on one hinge."},{"id":"LH-07-02-A-002","sp":"INEZ","dir":"radio","text":"Open outward. There's usually a bench behind it."},{"id":"LH-07-02-A-003","sp":"KIT","dir":"looking inside","text":"There was. Something's made a house out of it."},{"id":"LH-07-02-A-004","sp":"INEZ","dir":"a small smile in her voice","text":"Leave its things where they are."},{"id":"LH-07-02-A-005","sp":"KIT","dir":"examining the recorder","text":"Tape bay's closed. No standing water."},{"id":"LH-07-02-A-006","sp":"INEZ","dir":"careful excitement","text":"Good. Don't run anything through it yet."}],"journal":""},{"key":"07.02.B","title":"A swallowed test","kind":"If calibration fails","stage":"","notes":["On successful calibration, replace the above scene with:"],"lines":[{"id":"LH-07-02-B-001","sp":"KIT","dir":"stopping transport quickly","text":"Shit. Stop. It's folding."},{"id":"LH-07-02-B-002","sp":"INEZ","dir":"steady","text":"Power off. Don't pull the free end."},{"id":"LH-07-02-B-003","sp":"KIT","dir":"breathing, following","text":"Off."},{"id":"LH-07-02-B-004","sp":"INEZ","dir":"instruction","text":"Release the roller. Photograph how it sits before you move it."},{"id":"LH-07-02-B-005","sp":"KIT","dir":"recovering","text":"Test reel. That's why we used the test reel."},{"id":"LH-07-02-B-006","sp":"INEZ","dir":"confirming","text":"Exactly."},{"id":"LH-07-02-B-007","sp":"KIT","dir":"radio; pleased","text":"Test tone's steady. No drift at the marked interval."},{"id":"LH-07-02-B-008","sp":"INEZ","dir":"radio","text":"Then take the photographs. One reel at a time."}],"journal":""}]},{"id":"07.03","title":"How's Your Bed?","chapter":7,"target":75,"location":"relay with interactive listening bench","unlock":"","objectives":"load verified tape; align dropped-wrench transient; compare original question, first correction and second correction; log all timestamps.","gameplay":"20 media restoration, 25 synchronized listening/puzzle, 15 annotations, 15 reveal. Critical dialogue is replayable with subtitles and a visual waveform alternative.","success":"FULL_RADIO_CHRONOLOGY. No essential clue depends solely on hearing.","recovery":"incorrect alignment shifts the waveform back without destroying audio. Hints progress from source label to shared transient.","choice":"","notes":[],"scenes":[{"key":"07.03.A","title":"The question","kind":"Archive recording, clearance day 14:07","stage":"Record all archival lines cleanly. Tom's delivery is routine at first. Audible wrench drop is an SFX cue, not an actor vocalization.","notes":[],"lines":[{"id":"LH-07-03-A-001","sp":"TOM","dir":"radio; routine depot traffic","text":"Mercy truck, how's your bed?"},{"id":"LH-07-03-A-002","sp":"JUNE","dir":"radio; working, not solemn","text":"Mercy empty. Returning to depot."},{"id":"LH-07-03-A-003","sp":"TOM","dir":"radio; ordinary","text":"Received. Call before the bend. Crew's waiting for a load count."},{"id":"LH-07-03-A-004","sp":"KIT","dir":"present day; realization","text":"He asked about the bed."},{"id":"LH-07-03-A-005","sp":"INEZ","dir":"radio; listening remotely","text":"Play the next exchange."}],"journal":""},{"key":"07.03.B","title":"First correction","kind":"Archive recording, 14:11","stage":"","notes":["SFX: carrier interference cuts through the last word. The text transcription marks an interruption, not a hidden missing sentence."],"lines":[{"id":"LH-07-03-B-001","sp":"TOM","dir":"radio; distracted urgency","text":"Supervisor, correction on that entry. Empty vehicle, not settlement. Reyes reports people returned near the tank."},{"id":"LH-07-03-B-002","sp":"OWEN","dir":"radio; clipped, busy","text":"Copy. Send site confirmation."},{"id":"LH-07-03-B-003","sp":"TOM","dir":"radio","text":"I don't have a clear line from the site. Hold the crew until—"},{"id":"LH-07-03-B-004","sp":"KIT","dir":"present day; angry","text":"It's in the log. He told him."},{"id":"LH-07-03-B-005","sp":"INEZ","dir":"radio; grounding","text":"Mark what you can hear. Now the other channel."}],"journal":""},{"key":"07.03.C","title":"Second correction","kind":"Archive recording, 14:18","stage":"","notes":["SFX: engine noise swallows the transmission. June's receiver acknowledgement tone is audible."],"lines":[{"id":"LH-07-03-C-001","sp":"TOM","dir":"radio; deliberate","text":"June. People are back at the east tank. I need you to confirm collection before the crew moves."},{"id":"LH-07-03-C-002","sp":"JUNE","dir":"radio; alarm breaking through","text":"Say that again. Who's still there?"},{"id":"LH-07-03-C-003","sp":"TOM","dir":"radio","text":"Torres family. Reyes is trying the south approach."},{"id":"LH-07-03-C-004","sp":"JUNE","dir":"radio; forceful","text":"Hold the crew where they are. I'm going back."},{"id":"LH-07-03-C-005","sp":"TOM","dir":"radio","text":"Get me a received message from the site. June, I need you to stop and—"},{"id":"LH-07-03-C-006","sp":"KIT","dir":"present day; hollow","text":"She heard it."},{"id":"LH-07-03-C-007","sp":"INEZ","dir":"radio; gentle","text":"Yes."},{"id":"LH-07-03-C-008","sp":"KIT","dir":"anger and grief together","text":"She heard it, and she still signed the fucking form."},{"id":"LH-07-03-C-009","sp":"INEZ","dir":"radio; quiet","text":"Bring both recordings home."}],"journal":""}]},{"id":"07.04","title":"The Road That Gave","chapter":7,"target":75,"location":"relay, failed service road, safe descent and Torres home approach, 44 road kilometres","unlock":"","objectives":"inspect the old recovery anchor; match chassis repair photo; hear Ellis's account; phone Nico; request a visit without recording.","gameplay":"30 difficult return route, 15 terrain investigation, 15 conversation, 15 restorative camp/checkpoint.","success":"JUNE_ATTEMPT_CONFIRMED; UNRECORDED_VISIT_AGREED.","recovery":"failed crossing reloads at the last safe pull-off with inspected cargo preserved. The player may choose the long safe descent, trading distance for vehicle wear.","choice":"","notes":[],"scenes":[{"key":"07.04.A","title":"The patch","kind":"Site conversation over radio","stage":"","notes":[],"lines":[{"id":"LH-07-04-A-001","sp":"ELLIS","dir":"radio; memory clear","text":"Passenger side dropped. She said not to put my feet under it."},{"id":"LH-07-04-A-002","sp":"KIT","dir":"looking at the anchor","text":"You got her out?"},{"id":"LH-07-04-A-003","sp":"ELLIS","dir":"radio","text":"We got the truck out. Nico already had the family."},{"id":"LH-07-04-A-004","sp":"KIT","dir":"controlled","text":"Why didn't you say?"},{"id":"LH-07-04-A-005","sp":"ELLIS","dir":"radio; ashamed","text":"Because it sounds like an excuse when I tell it in that order."},{"id":"LH-07-04-A-006","sp":"KIT","dir":"after a breath","text":"Tell it in the order it happened."},{"id":"LH-07-04-A-007","sp":"ELLIS","dir":"radio; committing","text":"I can do that."}],"journal":""},{"key":"07.04.B","title":"Nico's answer","kind":"Telephone at safe camp","stage":"","notes":["Chapter exit: The archive case is placed in the garage safe. Kit leaves her recorder beside it before driving to Rosa."],"lines":[{"id":"LH-07-04-B-001","sp":"NICO","dir":"telephone; weary of the subject","text":"Did my mother give you this number?"},{"id":"LH-07-04-B-002","sp":"KIT","dir":"owning it","text":"Yes."},{"id":"LH-07-04-B-003","sp":"NICO","dir":"dry","text":"I'm changing it to the bakery. At least somebody gets a sale."},{"id":"LH-07-04-B-004","sp":"KIT","dir":"careful","text":"I've heard the full call. Did June help bring them out?"},{"id":"LH-07-04-B-005","sp":"NICO","dir":"plain","text":"She brought back the good skillet. I saved us. Can we leave it there?"},{"id":"LH-07-04-B-006","sp":"KIT","dir":"stung, then listening","text":"All right."},{"id":"LH-07-04-B-007","sp":"NICO","dir":"softening","text":"Go and see them. Take lunch. Leave the recorder in the truck."},{"id":"LH-07-04-B-008","sp":"KIT","dir":"a real decision","text":"I'll ask them if they want me there first."}],"journal":""}]}]},{"n":8,"title":"The Return Address","intro":"Planned gameplay: 240 minutes. Truth, permission and publication are separate objectives. Physical evidence can support a correction without exposing private testimony.","missions":[{"id":"08.01","title":"Lunch Without Tape","chapter":8,"target":60,"location":"bakery and Torres home, 24 road kilometres","unlock":"","objectives":"buy or prepare lunch; leave recorder in garage safe; ask Rosa and Mateo what they want preserved; mark private/public permissions separately.","gameplay":"20 travel, 10 lunch preparation, 20 household visit, 10 journal review.","success":"FAMILY_WISHES_RECORDED. If earlier interview was refused, this is the complete repair path.","recovery":"bringing a recorder prompts Kit to stow it before entering. Player may withdraw the visit without penalty and reschedule it in the same mission.","choice":"","notes":[],"scenes":[{"key":"08.01.A","title":"At the gate","kind":"Prior-conduct branch","stage":"","notes":[],"lines":[{"id":"LH-08-01-A-001","sp":"MATEO","dir":"if earlier interview respected","text":"No recorder?","cond":"earlier interview respected"},{"id":"LH-08-01-A-002","sp":"KIT","dir":"if respected","text":"At the garage. Lunch is real, though.","cond":"respected"},{"id":"LH-08-01-A-003","sp":"MATEO","dir":"if earlier interview mishandled; guarded","text":"We said enough last time.","cond":"earlier interview mishandled"},{"id":"LH-08-01-A-004","sp":"KIT","dir":"if mishandled; accountable","text":"I kept asking after you wanted me to stop. I won't do that again.","cond":"mishandled"},{"id":"LH-08-01-A-005","sp":"MATEO","dir":"if mishandled","text":"You can leave the food. Mum can decide about the visit.","cond":"mishandled"},{"id":"LH-08-01-A-006","sp":"ROSA","dir":"from the door; either branch","text":"I decided. Come in before it cools."}],"journal":""},{"key":"08.01.B","title":"Whose story","kind":"Kitchen","stage":"","notes":[],"lines":[{"id":"LH-08-01-B-001","sp":"ROSA","dir":"speaking for herself","text":"The house was blue before the water. They keep printing that grey photograph afterward."},{"id":"LH-08-01-B-002","sp":"KIT","dir":"listening","text":"Would you like the blue one in the correction?"},{"id":"LH-08-01-B-003","sp":"ROSA","dir":"deciding","text":"Yes. With the address covered."},{"id":"LH-08-01-B-004","sp":"MATEO","dir":"firm","text":"I don't want my interview on the radio."},{"id":"LH-08-01-B-005","sp":"KIT","dir":"writing the limit","text":"It won't be."},{"id":"LH-08-01-B-006","sp":"ROSA","dir":"careful","text":"I do want them to know we were there."},{"id":"LH-08-01-B-007","sp":"MATEO","dir":"to Rosa; understanding","text":"You can tell them."},{"id":"LH-08-01-B-008","sp":"KIT","dir":"making it explicit","text":"Separate decisions. Yours stays private, Mateo."},{"id":"LH-08-01-B-009","sp":"MATEO","dir":"relieved","text":"Good. Then I can tell you about the dog without it becoming evidence."}],"journal":""}]},{"id":"08.02","title":"Read It Back","chapter":8,"target":60,"location":"radio station, Fern and county fax point, 26 road kilometres","unlock":"","objectives":"assemble source order; separate fact, inference and recollection; read each statement back; correct Ellis's age and dates; obtain final permissions.","gameplay":"20 travel, 25 evidence and consent interaction, 15 scenes.","success":"EVIDENCE_READY. Permission withdrawal removes corresponding audio from public route but preserves an anonymized factual source with consent where allowed.","recovery":"incorrect source ordering receives an explanation, and witness limits remain visible in the journal.","choice":"","notes":[],"scenes":[{"key":"08.02.A","title":"The programme that waits","kind":"Radio station","stage":"","notes":[],"lines":[{"id":"LH-08-02-A-001","sp":"INEZ","dir":"reading Kit's summary","text":"'June confirmed the town was empty.' This paragraph still says it."},{"id":"LH-08-02-A-002","sp":"KIT","dir":"realizing","text":"That's the old transcription."},{"id":"LH-08-02-A-003","sp":"INEZ","dir":"pointing","text":"You pasted it into the correction."},{"id":"LH-08-02-A-004","sp":"KIT","dir":"angry at the mistake","text":"Fuck. All right. Give me the pencil."},{"id":"LH-08-02-A-005","sp":"INEZ","dir":"steady","text":"That's why we read it back."},{"id":"LH-08-02-A-006","sp":"ELLIS","dir":"looking at his statement","text":"You wrote I saw her sign it."},{"id":"LH-08-02-A-007","sp":"KIT","dir":"checking notes","text":"You said you saw the paper."},{"id":"LH-08-02-A-008","sp":"ELLIS","dir":"precise now","text":"Afterward. I didn't watch her hand."},{"id":"LH-08-02-A-009","sp":"KIT","dir":"correcting","text":"Afterward. Thank you."}],"journal":""},{"key":"08.02.B","title":"Fern's amendment","kind":"Doorstep","stage":"","notes":[],"lines":[{"id":"LH-08-02-B-001","sp":"FERN","dir":"reading","text":"'May have collected doors before sale completion.' Take my name off that sentence."},{"id":"LH-08-02-B-002","sp":"KIT","dir":"checking","text":"Because you didn't see who?"},{"id":"LH-08-02-B-003","sp":"FERN","dir":"firm","text":"Because I didn't see anybody. I saw an empty space later."},{"id":"LH-08-02-B-004","sp":"KIT","dir":"writing","text":"'Some lots were absent at collection. Collector unknown.'"},{"id":"LH-08-02-B-005","sp":"FERN","dir":"relieved","text":"That's mine."},{"id":"LH-08-02-B-006","sp":"KIT","dir":"sincerely","text":"You've made it harder to tell neatly."},{"id":"LH-08-02-B-007","sp":"FERN","dir":"a tired smile","text":"I lived it. It wasn't neat."}],"journal":""}]},{"id":"08.03","title":"The Question as Asked","chapter":8,"target":60,"location":"Calder meeting room","unlock":"","objectives":"present the synchronized excerpts; ask Owen about each decision point; allow witnesses to speak; agree an accurate meeting record.","gameplay":"15 preparation and permissions check, 30 interactive confrontation, 15 records handover.","success":"OWEN_ADMISSION; CORRECTION_ELIGIBLE. No confession is won with threats or combat.","recovery":"if the player interrupts repeatedly, Mara pauses the meeting and offers the same questions in written form. Answers below are supplied as Owen's recorded response, with matching alternate Kit framing.","choice":"","notes":[],"scenes":[{"key":"08.03.A","title":"Who checked?","kind":"Formal meeting","stage":"","notes":[],"lines":[{"id":"LH-08-03-A-001","sp":"MARA","dir":"opening","text":"Participants have agreed to this recording. Addresses stay out. Kit, first question."},{"id":"LH-08-03-A-002","sp":"KIT","dir":"controlled","text":"At fourteen eleven, the dispatcher corrected the vacancy entry. Who checked before the crew moved?"},{"id":"LH-08-03-A-003","sp":"OWEN","dir":"practised","text":"Reports were contradictory. June was returning."},{"id":"LH-08-03-A-004","sp":"KIT","dir":"specific","text":"Who checked?"},{"id":"LH-08-03-A-005","sp":"OWEN","dir":"after a pause","text":"I accepted the original report."},{"id":"LH-08-03-A-006","sp":"MARA","dir":"to Owen","text":"Please answer whether there was an on-site check."},{"id":"LH-08-03-A-007","sp":"OWEN","dir":"plain","text":"There wasn't."},{"id":"LH-08-03-A-008","sp":"ALMA","dir":"quiet from her chair","text":"Then put that in the minutes."}],"journal":""},{"key":"08.03.B","title":"Afterward","kind":"Confrontation continuation","stage":"","notes":[],"lines":[{"id":"LH-08-03-B-001","sp":"KIT","dir":"placing the evening form down","text":"You knew her truck had gone off the service road. You knew Nico brought people out."},{"id":"LH-08-03-B-002","sp":"OWEN","dir":"defensive","text":"Everyone had been brought out by then."},{"id":"LH-08-03-B-003","sp":"KIT","dir":"firm","text":"That's when you could have corrected the file."},{"id":"LH-08-03-B-004","sp":"OWEN","dir":"a loss of control","text":"We had people in motels, a failing bridge, contractors charging by the hour. Every fucking choice cost somebody."},{"id":"LH-08-03-B-005","sp":"MARA","dir":"calm boundary","text":"We can record the pressure. The question concerns the correction."},{"id":"LH-08-03-B-006","sp":"OWEN","dir":"after a long breath","text":"I saw the discrepancy. I left it in the file."},{"id":"LH-08-03-B-007","sp":"KIT","dir":"quiet","text":"Thank you for saying it."},{"id":"LH-08-03-B-008","sp":"OWEN","dir":"no absolution","text":"It doesn't change where I left it."},{"id":"LH-08-03-B-009","sp":"NICO","dir":"steady","text":"It changes what the next person reads."}],"journal":""},{"key":"08.03.C","title":"Written-response route","kind":"Only if meeting paused","stage":"","notes":[],"lines":[{"id":"LH-08-03-C-001","sp":"MARA","dir":"reading Owen's signed response","text":"'No further on-site confirmation was obtained before clearance proceeded. I became aware of the discrepancy afterward and did not amend the record.'"},{"id":"LH-08-03-C-002","sp":"KIT","dir":"receiving it","text":"Put the question beside it. Exactly as asked."},{"id":"LH-08-03-C-003","sp":"MARA","dir":"agreeing","text":"It stays attached."}],"journal":""}]},{"id":"08.04","title":"A Place to Come Back To","chapter":8,"target":60,"location":"Calder, garage and motel, 30 road kilometres","unlock":"","objectives":"store correction package; learn service-permit requirements; deliver trial invitation to Lorna and Del; choose whether to explore running or handing over a route.","gameplay":"25 driving, 15 route requirements inspection, 10 basic vehicle capacity check, 10 dialogue.","success":"TRIAL_INVITED. Choice INTENT_STAY or INTENT_HANDOVER changes later dialogue, not access to route development.","recovery":"existing pickup lacks enough passenger seats for the final trial; Ada supplies written requirements, and chapter 9 provides a real multi-seat vehicle. No magical capacity change.","choice":"","notes":[],"scenes":[{"key":"08.04.A","title":"The permit notice","kind":"Garage","stage":"","notes":[],"lines":[{"id":"LH-08-04-A-001","sp":"ADA","dir":"introducing herself","text":"Ada Finch. County passenger services. Mara said you know where people are actually living now."},{"id":"LH-08-04-A-002","sp":"KIT","dir":"wary","text":"Is that a job offer or another form?"},{"id":"LH-08-04-A-003","sp":"ADA","dir":"small smile","text":"First a question. Seasonal permit's due. Is anyone proposing a route?"},{"id":"LH-08-04-A-004","sp":"DEL","dir":"looking at the pickup","text":"Not with one passenger seat."},{"id":"LH-08-04-A-005","sp":"ADA","dir":"confirming","text":"Correct. I inspect the vehicle and ride the trial. I don't invent seats for good intentions."},{"id":"LH-08-04-A-006","sp":"KIT","dir":"thinking","text":"How long have we got?"},{"id":"LH-08-04-A-007","sp":"ADA","dir":"handing notice","text":"Next Saturday. If you're not ready, request another date."}],"journal":""},{"key":"08.04.B","title":"Kit's intention","kind":"Motel porch","stage":"","notes":["Chapter exit: Kit opens a fresh ledger page headed 'Saturday service'."],"lines":[{"id":"LH-08-04-B-001","sp":"ALMA","dir":"quiet question","text":"Are you staying?"},{"id":"LH-08-04-B-002","sp":"KIT","dir":"INTENT_STAY; cautious","text":"I want to see if I can make the garage work.","branch":"INTENT_STAY"},{"id":"LH-08-04-B-003","sp":"ALMA","dir":"INTENT_STAY","text":"Then find work you can keep doing.","branch":"INTENT_STAY"},{"id":"LH-08-04-B-004","sp":"KIT","dir":"INTENT_HANDOVER; honest","text":"I don't know if living here is mine to promise. I can help somebody else get a route running.","branch":"INTENT_HANDOVER"},{"id":"LH-08-04-B-005","sp":"ALMA","dir":"INTENT_HANDOVER","text":"Say that at the start. People can plan around it.","branch":"INTENT_HANDOVER"},{"id":"LH-08-04-B-006","sp":"KIT","dir":"looking at the door table","text":"I came here to return one thing."},{"id":"LH-08-04-B-007","sp":"ALMA","dir":"gentle humour","text":"And I asked you to collect chairs. You should have suspected."}],"journal":""}]}]},{"n":9,"title":"A Route People Can Use","intro":"Planned gameplay: 300 minutes. Four route-development missions. Earlier relationships reduce costs or provide backup but do not create an unwinnable campaign.","missions":[{"id":"09.01","title":"Seats Count","chapter":9,"target":75,"location":"county surplus yard, garage and parts depot, 34 road kilometres","unlock":"","objectives":"inspect an eight-seat community minibus; choose county loan or repair partnership; restore brakes, tyres and cooling; verify all seat mountings.","gameplay":"20 inspection, 30 repair and sourcing, 15 driving, 10 scenes.","success":"BUS_READY; vehicle 'Mercy Eight' has seven passenger seats and one driver seat.","recovery":"failed safety check identifies the actual fault. County loan includes required safety parts, so low cash cannot stall the story.","choice":"","notes":["Economy: COUNTY_LOAN has no upfront fee and an operating-cost deduction. COOP_REPAIR uses contributions unlocked by deliveries. Both use the same safe vehicle."],"scenes":[{"key":"09.01.A","title":"Surplus","kind":"Yard","stage":"","notes":[],"lines":[{"id":"LH-09-01-A-001","sp":"ADA","dir":"opening the bus","text":"Eight seats including yours. Service record's in the pouch."},{"id":"LH-09-01-A-002","sp":"KIT","dir":"checking a mounting","text":"When did it last run?"},{"id":"LH-09-01-A-003","sp":"ADA","dir":"reading","text":"Six months ago. Parked for cooling loss."},{"id":"LH-09-01-A-004","sp":"ELLIS","dir":"under the bonnet","text":"Hose split. There's a proper repair and a version June would've done with tape."},{"id":"LH-09-01-A-005","sp":"KIT","dir":"deciding","text":"We're doing the proper one."},{"id":"LH-09-01-A-006","sp":"ADA","dir":"matter-of-fact","text":"That's the one I'll inspect."},{"id":"LH-09-01-A-007","sp":"ELLIS","dir":"a little relieved","text":"Good. Easier to agree before somebody gets attached to the tape."}],"journal":""},{"key":"09.01.B","title":"Funding choice","kind":"At the desk","stage":"","notes":[],"lines":[{"id":"LH-09-01-B-001","sp":"ADA","dir":"explaining","text":"Loan arrangement covers safety parts. You pay an operating share once fares start."},{"id":"LH-09-01-B-002","sp":"KIT","dir":"COUNTY_LOAN","text":"Put the share and the due dates in the agreement. I want the cost before I take the keys.","branch":"COUNTY_LOAN"},{"id":"LH-09-01-B-003","sp":"ADA","dir":"COUNTY_LOAN","text":"Sensible. Read this copy here.","branch":"COUNTY_LOAN"},{"id":"LH-09-01-B-004","sp":"ELLIS","dir":"COOP_REPAIR","text":"Lorna can put money in. Manny's got sound tyres. I've got labour.","branch":"COOP_REPAIR"},{"id":"LH-09-01-B-005","sp":"KIT","dir":"COOP_REPAIR","text":"Nobody contributes until we write who owns what.","branch":"COOP_REPAIR"},{"id":"LH-09-01-B-006","sp":"ADA","dir":"COOP_REPAIR; approving","text":"Bring me the ownership agreement with the inspection.","branch":"COOP_REPAIR"},{"id":"LH-09-01-B-007","sp":"KIT","dir":"turning the ignition after repair","text":"Seven seats. Seven actual people."},{"id":"LH-09-01-B-008","sp":"ELLIS","dir":"smiling","text":"Try moving it before you get sentimental."}],"journal":""}]},{"id":"09.02","title":"Before the First Stop","chapter":9,"target":75,"location":"Lorna's home, motel, clinic and Calder bakery, 32 road kilometres","unlock":"","objectives":"walk Lorna's approach; measure bus access; interview clinic passenger Del and visiting daughter Edie; test three stop locations.","gameplay":"15 walking and access assessment, 25 driving timed segments, 20 timetable interaction, 15 scenes.","success":"PASSENGER_NEEDS_LOGGED. Moving the motel stop sets SAFE_STOP; retaining it requires a lit waiting place and extra approach allowance.","recovery":"inaccessible stop can be changed without restarting the journey. Route planner shows travel time and walking time separately.","choice":"","notes":[],"scenes":[{"key":"09.02.A","title":"Twenty minutes","kind":"At Lorna's gate","stage":"","notes":[],"lines":[{"id":"LH-09-02-A-001","sp":"LORNA","dir":"looking at proposed sheet","text":"Where does this start?"},{"id":"LH-09-02-A-002","sp":"KIT","dir":"showing map","text":"Motel stop."},{"id":"LH-09-02-A-003","sp":"LORNA","dir":"direct","text":"I don't live at the motel."},{"id":"LH-09-02-A-004","sp":"DEL","dir":"trying to help","text":"We know."},{"id":"LH-09-02-A-005","sp":"LORNA","dir":"pointing at the blank space","text":"Then where's the bit before it?"},{"id":"LH-09-02-A-006","sp":"KIT","dir":"recognizing omission","text":"The walk."},{"id":"LH-09-02-A-007","sp":"LORNA","dir":"controlled","text":"In the dark. Through the gutter. Carrying work shoes so they stay dry."},{"id":"LH-09-02-A-008","sp":"KIT","dir":"turning the page","text":"Show me. We'll time it from your door."}],"journal":""},{"key":"09.02.B","title":"The appointment","kind":"Clinic forecourt","stage":"","notes":[],"lines":[{"id":"LH-09-02-B-001","sp":"DEL","dir":"reading appointment","text":"Not before nine. If you get me there early, I wait outside."},{"id":"LH-09-02-B-002","sp":"KIT","dir":"writing","text":"Shelter, arrival window, return."},{"id":"LH-09-02-B-003","sp":"DEL","dir":"watching","text":"Make the return leg big enough to read."},{"id":"LH-09-02-B-004","sp":"EDIE","dir":"joining them","text":"Can you take me to my father's place after his lunch?"},{"id":"LH-09-02-B-005","sp":"KIT","dir":"checking the draft","text":"That makes the clinic pickup tight."},{"id":"LH-09-02-B-006","sp":"LORNA","dir":"automatically offering","text":"I'll find another lift."},{"id":"LH-09-02-B-007","sp":"DEL","dir":"firm","text":"No. We always start by taking your seat away."},{"id":"LH-09-02-B-008","sp":"KIT","dir":"to Edie","text":"Could we ask him about breakfast instead?"},{"id":"LH-09-02-B-009","sp":"EDIE","dir":"surprised, then amused","text":"He'd love that. He keeps telling me breakfast is a meal people have forgotten."}],"journal":""}]},{"id":"09.03","title":"Recovery Time","chapter":9,"target":75,"location":"full proposed loop, 42 road kilometres","unlock":"","objectives":"run an unlicensed empty-route practice with invited observers; stop safely; simulate one cancelled pickup; respond to a controlled cooling fault; revise connections.","gameplay":"35 driving, 15 roadside repair, 15 planner revision, 10 scenes.","success":"TRIAL_ROUTE_REVISED; BACKUP_PLAN chosen from Ellis pickup, Manny vehicle or county reserve contact.","recovery":"vehicle unsafe to continue triggers observer assistance, then repeat only the failed route segment.","choice":"","notes":["Fault is a declared training scenario using a removable test restriction. It is removed after diagnosis. The game never secretly damages a newly repaired bus for drama."],"scenes":[{"key":"09.03.A","title":"A reason to stop","kind":"Briefing","stage":"","notes":[],"lines":[{"id":"LH-09-03-A-001","sp":"ADA","dir":"before practice","text":"Today's empty-route exercise. We aren't carrying paying passengers."},{"id":"LH-09-03-A-002","sp":"KIT","dir":"checking clipboard","text":"Stops, turn, connections. What's the fault?"},{"id":"LH-09-03-A-003","sp":"ADA","dir":"clear","text":"Ellis has fitted a removable cooling restriction. When the gauge rises, stop and diagnose. He removes it after."},{"id":"LH-09-03-A-004","sp":"ELLIS","dir":"showing the part","text":"Orange tag. Doesn't leave the yard on Saturday."},{"id":"LH-09-03-A-005","sp":"KIT","dir":"a little amused","text":"A breakdown with paperwork. Luxury."}],"journal":""},{"key":"09.03.B","title":"At the shoulder","kind":"During training fault","stage":"","notes":[],"lines":[{"id":"LH-09-03-B-001","sp":"LORNA","dir":"watching the gauge","text":"Is that where you wanted it?"},{"id":"LH-09-03-B-002","sp":"KIT","dir":"taking control","text":"Enough. Indicator. Safe shoulder. Engine off."},{"id":"LH-09-03-B-003","sp":"DEL","dir":"assessing","text":"People get out away from the road."},{"id":"LH-09-03-B-004","sp":"KIT","dir":"to observers","text":"Away side, please. Shade's behind the barrier."},{"id":"LH-09-03-B-005","sp":"ELLIS","dir":"once safe","text":"What's your first check?"},{"id":"LH-09-03-B-006","sp":"KIT","dir":"working","text":"Coolant level when it's safe. Hoses. Airflow. Then your orange bloody souvenir."},{"id":"LH-09-03-B-007","sp":"ADA","dir":"calm","text":"And the passenger who's missing a connection?"},{"id":"LH-09-03-B-008","sp":"KIT","dir":"remembering the radio","text":"Backup driver. I forgot to call the backup driver."}],"journal":""},{"key":"09.03.C","title":"The revised sheet","kind":"After practice","stage":"","notes":[],"lines":[{"id":"LH-09-03-C-001","sp":"KIT","dir":"marking delay","text":"Six minutes at the depot. Recovery time."},{"id":"LH-09-03-C-002","sp":"LORNA","dir":"remembering","text":"I walked past that bus for years while it stood there."},{"id":"LH-09-03-C-003","sp":"DEL","dir":"taking the point","text":"I never asked where you were going after."},{"id":"LH-09-03-C-004","sp":"LORNA","dir":"not letting him escape into apology","text":"Ask now."},{"id":"LH-09-03-C-005","sp":"DEL","dir":"sincerely","text":"How far from the stop to the ovens?"},{"id":"LH-09-03-C-006","sp":"LORNA","dir":"ready","text":"Fifteen minutes if the gate's open."},{"id":"LH-09-03-C-007","sp":"KIT","dir":"adding it","text":"Then that's part of the route."}],"journal":""}]},{"id":"09.04","title":"What Belongs to You","chapter":9,"target":75,"location":"garage, checkpoint/bypass and motel, 35 road kilometres","unlock":"","objectives":"post timetable; confirm backup; finalize road access; settle selected garage obligations; prepare recording decision with Mara.","gameplay":"25 posting and road visits, 20 vehicle preparation, 15 ledger decisions, 15 scenes.","success":"SATURDAY_READY. Kit's final intent selected as RUN, COOPERATE or HANDOVER. A fourth LEAVE_UNARRANGED outcome is permitted only after clear warnings and does not block trial.","recovery":"a refused agreement automatically opens bypass revision. Kit can request more preparation days before starting chapter 10.","choice":"","notes":["Checkpoint civil: signed fixed access agreement. Hostile: surveyed bypass with 12 additional kilometres and revised departure times."],"scenes":[{"key":"09.04.A","title":"The line in writing","kind":"Road-access branch","stage":"","notes":[],"lines":[{"id":"LH-09-04-A-001","sp":"SERA","dir":"civil; reading","text":"No collection from individual passengers."},{"id":"LH-09-04-A-002","sp":"KIT","dir":"civil; firm","text":"Vehicle fee only. Same every run. You close for repairs, you tell us before we leave."},{"id":"LH-09-04-A-003","sp":"SERA","dir":"civil","text":"And your driver keeps out of Len's work area."},{"id":"LH-09-04-A-004","sp":"KIT","dir":"civil","text":"Agreed."},{"id":"LH-09-04-A-005","sp":"SERA","dir":"civil; signing","text":"I suppose we're both becoming people who keep copies."},{"id":"LH-09-04-A-006","sp":"LEN","dir":"hostile-route branch; at bypass","text":"Shoulder's marked. Use the inland turn if the wash is wet."},{"id":"LH-09-04-A-007","sp":"KIT","dir":"hostile-route branch","text":"Departure's earlier. Nobody pays the checkpoint."},{"id":"LH-09-04-A-008","sp":"LEN","dir":"hostile-route branch","text":"Tell them why. Don't make it sound like you just like dawn."}],"journal":""},{"key":"09.04.B","title":"The ledger","kind":"Night at the garage","stage":"","notes":["Chapter exit: Kit lays out keys, water and the departure sheet. No revelation tape from June follows this scene."],"lines":[{"id":"LH-09-04-B-001","sp":"ELLIS","dir":"looking at the fresh page","text":"You copied her debts."},{"id":"LH-09-04-B-002","sp":"KIT","dir":"correcting","text":"I copied the jobs. Some money's already been paid. Some things were gifts she couldn't call gifts."},{"id":"LH-09-04-B-003","sp":"ELLIS","dir":"asking carefully","text":"And the promises?"},{"id":"LH-09-04-B-004","sp":"KIT","dir":"RUN","text":"I'll run the route. I'm not promising every errand in this book.","branch":"RUN"},{"id":"LH-09-04-B-005","sp":"KIT","dir":"COOPERATE","text":"We divide the work tomorrow. Nobody gets a timetable built around one person's guilt.","branch":"COOPERATE"},{"id":"LH-09-04-B-006","sp":"KIT","dir":"HANDOVER","text":"I'll do the trial, train the next driver, and leave a service somebody else can run.","branch":"HANDOVER"},{"id":"LH-09-04-B-007","sp":"KIT","dir":"LEAVE_UNARRANGED","text":"I'll do the trial. After that, I still haven't got an answer.","branch":"LEAVE_UNARRANGED"},{"id":"LH-09-04-B-008","sp":"ELLIS","dir":"LEAVE_UNARRANGED; honest","text":"Then don't tell people you have.","branch":"LEAVE_UNARRANGED"},{"id":"LH-09-04-B-009","sp":"ELLIS","dir":"offering","text":"I can be here at six."},{"id":"LH-09-04-B-010","sp":"KIT","dir":"specific","text":"Five forty-five. Check the tyres."},{"id":"LH-09-04-B-011","sp":"ELLIS","dir":"smiling","text":"Five forty-five. An actual promise."}],"journal":""}]}]},{"n":10,"title":"Saturday Service","intro":"Planned gameplay: 240 minutes. The final Saturday occurs several weeks after the first memorial supper. No player is forced to skip sleep to meet a story clock.","missions":[{"id":"10.01","title":"Five Forty-Five","chapter":10,"target":60,"location":"garage to first public stop, 18 road kilometres","unlock":"","objectives":"complete inspection; verify orange test restriction removed; load emergency supplies; reserve mobility space; greet Ada; depart to posted time.","gameplay":"25 checks and loading, 15 road approach, 10 boarding simulation, 10 opening scenes.","success":"TRIAL_RUNNING. PREP_SCORE logs real completed actions; missing critical safety item prevents departure with clear reason.","recovery":"all mandatory safety supplies exist at the garage. Player may postpone the date without losing campaign progress.","choice":"","notes":[],"scenes":[{"key":"10.01.A","title":"The inspection","kind":"Dawn","stage":"","notes":[],"lines":[{"id":"LH-10-01-A-001","sp":"ELLIS","dir":"from beside tyre","text":"Five forty-three."},{"id":"LH-10-01-A-002","sp":"KIT","dir":"checking clock","text":"You're early."},{"id":"LH-10-01-A-003","sp":"ELLIS","dir":"matter-of-fact","text":"Wanted to try it once."},{"id":"LH-10-01-A-004","sp":"ADA","dir":"arriving with clipboard","text":"Morning. Show me the fault-training tag."},{"id":"LH-10-01-A-005","sp":"KIT","dir":"holding disconnected part","text":"Removed, signed off, here."},{"id":"LH-10-01-A-006","sp":"ADA","dir":"checking","text":"Good. Emergency exits next."},{"id":"LH-10-01-A-007","sp":"KIT","dir":"opening the far door","text":"Two. Both clear."},{"id":"LH-10-01-A-008","sp":"ALMA","dir":"with a jar","text":"Put this somewhere it won't roll."},{"id":"LH-10-01-A-009","sp":"KIT","dir":"amused","text":"Is that an inspection requirement?"},{"id":"LH-10-01-A-010","sp":"ALMA","dir":"firm","text":"Peaches are a travel requirement."}],"journal":""},{"key":"10.01.B","title":"Before departure","kind":"Cab scene","stage":"","notes":[],"lines":[{"id":"LH-10-01-B-001","sp":"DEL","dir":"settling in passenger seat","text":"I can keep quiet while you drive."},{"id":"LH-10-01-B-002","sp":"KIT","dir":"a small smile","text":"Put it in writing."},{"id":"LH-10-01-B-003","sp":"ADA","dir":"at the door","text":"I'm recording what happens. Explain changes to passengers before you make them."},{"id":"LH-10-01-B-004","sp":"KIT","dir":"acknowledging","text":"Departure, destination, return. All on the sheet."},{"id":"LH-10-01-B-005","sp":"LORNA","dir":"from the stop","text":"And the gate after the bakery."},{"id":"LH-10-01-B-006","sp":"KIT","dir":"calling back","text":"I haven't forgotten the bloody gate."},{"id":"LH-10-01-B-007","sp":"LORNA","dir":"pleased","text":"Good morning to you too."}],"journal":""}]},{"id":"10.02","title":"Everybody Has Somewhere","chapter":10,"target":60,"location":"chosen public loop, 26 kilometres civil or 38 bypass","unlock":"","objectives":"collect Alma, Lorna, Del and Edie at four stops; provide safe boarding; reach bakery and clinic within agreed windows; handle one late passenger.","gameplay":"30 multi-stop driving, 15 boarding/access, 10 route communication, 5 short exchanges.","success":"FIRST_LEG_COMPLETE.","recovery":"missed clinic arrival prompts Ada to phone the clinic; an accepted later slot preserves service at reduced punctuality score.","choice":"","notes":["Late passenger is Edie. Choice WAIT_EDIE shifts connection margin; CHOOSE_BACKUP_EDIE sends confirmed backup; DEPART_UNEXPLAINED records a service failure. No penalty for respecting an agreed wait window."],"scenes":[{"key":"10.02.A","title":"The first fare","kind":"Motel","stage":"","notes":[],"lines":[{"id":"LH-10-02-A-001","sp":"ALMA","dir":"boarding with care","text":"I've got the right money."},{"id":"LH-10-02-A-002","sp":"KIT","dir":"offering a hand without pulling","text":"Step's dry. Rail on your left."},{"id":"LH-10-02-A-003","sp":"ALMA","dir":"appreciative","text":"I'll do it. Stay where I can see you."},{"id":"LH-10-02-A-004","sp":"KIT","dir":"letting her set the pace","text":"All right."},{"id":"LH-10-02-A-005","sp":"ALMA","dir":"seated","text":"You can leave now. I won't turn this into a ceremony."}],"journal":""},{"key":"10.02.B","title":"Edie's call","kind":"Choice scene at safe stop","stage":"","notes":[],"lines":[{"id":"LH-10-02-B-001","sp":"EDIE","dir":"phone; breathless","text":"Gate wouldn't open. I'm coming down the lane."},{"id":"LH-10-02-B-002","sp":"KIT","dir":"WAIT_EDIE","text":"Take the safe way. We agreed three minutes. You've still got two.","branch":"WAIT_EDIE"},{"id":"LH-10-02-B-003","sp":"EDIE","dir":"WAIT_EDIE; relieved","text":"Thank you. Don't let Del tell the cake story until I get there.","branch":"WAIT_EDIE"},{"id":"LH-10-02-B-004","sp":"KIT","dir":"CHOOSE_BACKUP_EDIE","text":"We're at the wait limit. I've confirmed your backup. Stay by the lit gate; they'll take you to breakfast.","branch":"CHOOSE_BACKUP_EDIE"},{"id":"LH-10-02-B-005","sp":"EDIE","dir":"CHOOSE_BACKUP_EDIE","text":"Who's coming?","branch":"CHOOSE_BACKUP_EDIE"},{"id":"LH-10-02-B-006","sp":"KIT","dir":"CHOOSE_BACKUP_EDIE","text":"The driver named on your message. I'm sending their arrival time now.","branch":"CHOOSE_BACKUP_EDIE"},{"id":"LH-10-02-B-007","sp":"EDIE","dir":"DEPART_UNEXPLAINED; voicemail received at next stop","text":"Kit, the bus has gone. I don't know if you're coming back.","branch":"DEPART_UNEXPLAINED"},{"id":"LH-10-02-B-008","sp":"ADA","dir":"DEPART_UNEXPLAINED; to Kit at stop","text":"Tell her what happens next. Silence isn't a transport plan.","branch":"DEPART_UNEXPLAINED"}],"journal":""},{"key":"10.02.C","title":"The bakery window","kind":"Destination","stage":"","notes":[],"lines":[{"id":"LH-10-02-C-001","sp":"LORNA","dir":"checking time","text":"Before the dough warmed up."},{"id":"LH-10-02-C-002","sp":"KIT","dir":"pleased but watching road","text":"Is that good?"},{"id":"LH-10-02-C-003","sp":"LORNA","dir":"dry","text":"Put it in your report."},{"id":"LH-10-02-C-004","sp":"DEL","dir":"to Ada","text":"She's been waiting years to give a driver a review."},{"id":"LH-10-02-C-005","sp":"ADA","dir":"writing","text":"I'll record the actual words."}],"journal":""}]},{"id":"10.03","title":"The Return Leg","chapter":10,"target":60,"location":"clinic, camp connection and garage, 30 road kilometres","unlock":"","objectives":"collect Del; respond to an injured-road-user delay without unsafe stopping; protect the final connection; activate backup or explain a revised route.","gameplay":"25 driving, 15 safe breakdown assessment, 10 communication and choice, 10 consequences.","success":"TRIAL_COMPLETE. Unsafe choices reload at the pull-off. Never end campaign over a single missed bus.","recovery":"","choice":"","notes":["Incident: Manny's parked van has a puncture, not an injured passenger. One passenger needs to reach a visiting-hours connection. Branch PREPARED_BACKUP uses confirmed driver and repair gear to satisfy both. WAIT_AND_REPAIR helps Manny but risks connection; CONTINUE_AND_REPORT sends roadside assistance and keeps the original run.","Score assesses communication and safe actions, not a single morally correct answer. Roadside assistance is a telephone scene, not an uncast voice."],"scenes":[{"key":"10.03.A","title":"The van","kind":"Safe pull-off","stage":"","notes":[],"lines":[{"id":"LH-10-03-A-001","sp":"MANNY","dir":"trying to make light","text":"Joke's on me. Spare's flatter than the tyre."},{"id":"LH-10-03-A-002","sp":"KIT","dir":"looking over traffic","text":"Everyone stay behind the barrier."},{"id":"LH-10-03-A-003","sp":"ADA","dir":"observing without directing","text":"Your passenger's connection is in eighteen minutes."},{"id":"LH-10-03-A-004","sp":"DEL","dir":"to Kit; quietly","text":"Ask what help he needs before you promise all of it."},{"id":"LH-10-03-A-005","sp":"KIT","dir":"to Manny","text":"Is everybody safe?"},{"id":"LH-10-03-A-006","sp":"MANNY","dir":"plain","text":"Yes. I need a wheel and someone to get Edie's bag to the camp."},{"id":"LH-10-03-A-007","sp":"KIT","dir":"working out options","text":"That's two jobs."}],"journal":""},{"key":"10.03.B","title":"Selected plan","kind":"Radio and cab","stage":"","notes":[],"lines":[{"id":"LH-10-03-B-001","sp":"KIT","dir":"PREPARED_BACKUP; radio","text":"Backup confirmed. Collect the camp passenger here, then take the posted connection. I'm with the van.","branch":"PREPARED_BACKUP"},{"id":"LH-10-03-B-002","sp":"ELLIS","dir":"if Ellis backup","text":"Received. I've got the route sheet and a sound spare.","cond":"Ellis backup"},{"id":"LH-10-03-B-003","sp":"MANNY","dir":"if Manny is backup, now unavailable; revised backup required","text":"Don't count my van twice. Ring the county reserve number.","cond":"Manny is backup, now unavailable"},{"id":"LH-10-03-B-004","sp":"ADA","dir":"if county reserve activated; telephone then to Kit","text":"Reserve driver confirmed. Same passenger list, twenty-minute transfer. Explain it to them.","cond":"county reserve activated"},{"id":"LH-10-03-B-005","sp":"KIT","dir":"WAIT_AND_REPAIR; to passengers","text":"I'm staying for the repair. This will cost the connection unless the depot can hold it. I'm asking now.","branch":"WAIT_AND_REPAIR"},{"id":"LH-10-03-B-006","sp":"EDIE","dir":"WAIT_AND_REPAIR","text":"Call my father too. He shouldn't be waiting at the other end wondering.","branch":"WAIT_AND_REPAIR"},{"id":"LH-10-03-B-007","sp":"KIT","dir":"CONTINUE_AND_REPORT; to Manny","text":"I've called the repair desk. They have your location. Water's here. We're keeping the passenger run.","branch":"CONTINUE_AND_REPORT"},{"id":"LH-10-03-B-008","sp":"MANNY","dir":"CONTINUE_AND_REPORT; accepting","text":"Good. Ring when they're actually on their way.","branch":"CONTINUE_AND_REPORT"},{"id":"LH-10-03-B-009","sp":"KIT","dir":"CONTINUE_AND_REPORT","text":"I will.","branch":"CONTINUE_AND_REPORT"}],"journal":""},{"key":"10.03.C","title":"Return fare","kind":"After Del is collected","stage":"","notes":[],"lines":[{"id":"LH-10-03-C-001","sp":"DEL","dir":"getting in","text":"Thought you'd forgotten the part where I come home."},{"id":"LH-10-03-C-002","sp":"KIT","dir":"checking his name","text":"It's the largest word on the sheet."},{"id":"LH-10-03-C-003","sp":"DEL","dir":"sitting, relieved","text":"Good."},{"id":"LH-10-03-C-004","sp":"KIT","dir":"if connection made","text":"Everybody's got a way back.","cond":"connection made"},{"id":"LH-10-03-C-005","sp":"KIT","dir":"if connection missed","text":"Edie's father knows she's delayed. I've booked the later transfer.","cond":"connection missed"},{"id":"LH-10-03-C-006","sp":"ADA","dir":"if connection missed","text":"Record the miss and the recovery. Both happened.","cond":"connection missed"},{"id":"LH-10-03-C-007","sp":"DEL","dir":"quiet humour","text":"And put down that I complained. Otherwise nobody will believe I was here."}],"journal":""}]},{"id":"10.04","title":"The Correction","chapter":10,"target":60,"location":"county terminus, radio station and garage","unlock":"","objectives":"hear trial assessment; choose RUN/COOPERATE/HANDOVER/LEAVE_UNARRANGED intent; choose publication route; return to garage; answer the bell.","gameplay":"10 service assessment, 15 final permissions and publication interaction, 15 return drive, 20 ending scenes.","success":"","recovery":"","choice":"","notes":["Assessment: PASS when all safety checks and at least three service obligations fulfilled; CONDITIONAL when safe operation but missed obligations; REVISE when unsafe trial stopped. All allow ending. Free roam tracks unfinished service work.","Publication: PUBLIC_REDACTED broadcasts cleared excerpts; FAMILY_CONTROLLED gives sealed copies to consenting households; PRIVATE_CORRECTION files factual correction with no broadcast. Every route files the accurate public administrative correction. Private statements remain private in all routes.","Progress state: ENDING_FILED. Enter persistent free roam at the garage with route state and publication state saved."],"scenes":[{"key":"10.04.A","title":"What ran","kind":"Permit decision","stage":"","notes":[],"lines":[{"id":"LH-10-04-A-001","sp":"ADA","dir":"PASS","text":"Safe operation. Stops and return journeys accounted for. I'm recommending approval on the route you actually drove.","branch":"PASS"},{"id":"LH-10-04-A-002","sp":"KIT","dir":"PASS; cautiously pleased","text":"That's the one we're keeping.","branch":"PASS"},{"id":"LH-10-04-A-003","sp":"ADA","dir":"CONDITIONAL","text":"Safe vehicle. The connection needs revising. Conditional approval for the shorter route, then another observed run.","branch":"CONDITIONAL"},{"id":"LH-10-04-A-004","sp":"KIT","dir":"CONDITIONAL","text":"I'll post the shorter sheet before taking another fare.","branch":"CONDITIONAL"},{"id":"LH-10-04-A-005","sp":"ADA","dir":"REVISE","text":"I can't approve this run. You stopped when it became unsafe. Now we correct the plan and try again.","branch":"REVISE"},{"id":"LH-10-04-A-006","sp":"KIT","dir":"REVISE; disappointed, steady","text":"Give me the failures in writing. I'll work from those.","branch":"REVISE"},{"id":"LH-10-04-A-007","sp":"ADA","dir":"closing clipboard","text":"A timetable is something people lend their day to. Keep making it possible to lend you another."}],"journal":""},{"key":"10.04.B","title":"Who runs tomorrow","kind":"Four service endings","stage":"","notes":[],"lines":[{"id":"LH-10-04-B-001","sp":"KIT","dir":"RUN; to Ellis","text":"I'll drive. You'll have workshop hours, not an open invitation to fix everything I break.","branch":"RUN"},{"id":"LH-10-04-B-002","sp":"ELLIS","dir":"RUN; warm","text":"Put the hours on the door. I'll keep them.","branch":"RUN"},{"id":"LH-10-04-B-003","sp":"KIT","dir":"COOPERATE; at table","text":"Shared vehicle. Shared books. Lorna gets a say in times before we print them.","branch":"COOPERATE"},{"id":"LH-10-04-B-004","sp":"LORNA","dir":"COOPERATE","text":"Put the return trip on the first page.","branch":"COOPERATE"},{"id":"LH-10-04-B-005","sp":"DEL","dir":"COOPERATE","text":"I'll take bookings. No driving. That's the boundary.","branch":"COOPERATE"},{"id":"LH-10-04-B-006","sp":"KIT","dir":"HANDOVER; to Lorna and Ellis","text":"I'll finish training the driver and settle the repair list. Then I'm going back.","branch":"HANDOVER"},{"id":"LH-10-04-B-007","sp":"ELLIS","dir":"HANDOVER; with feeling","text":"You'll ring when you get there?","branch":"HANDOVER"},{"id":"LH-10-04-B-008","sp":"KIT","dir":"HANDOVER","text":"When I've parked. Like an actual person with a phone.","branch":"HANDOVER"},{"id":"LH-10-04-B-009","sp":"KIT","dir":"LEAVE_UNARRANGED; to Alma","text":"I haven't arranged someone to take it on. I won't pretend I have.","branch":"LEAVE_UNARRANGED"},{"id":"LH-10-04-B-010","sp":"ALMA","dir":"LEAVE_UNARRANGED; disappointed, kind","text":"Then we'll tell people the service ends Friday. They deserve the time to ask someone else.","branch":"LEAVE_UNARRANGED"}],"journal":""},{"key":"10.04.C","title":"Three copies","kind":"Final publication choice","stage":"","notes":[],"lines":[{"id":"LH-10-04-C-001","sp":"MARA","dir":"laying folders down","text":"Administrative correction in all three. The difference is who releases the cleared recordings."},{"id":"LH-10-04-C-002","sp":"INEZ","dir":"to Kit","text":"Public programme, copies for the families, or the correction alone. Nobody's private statement goes out with any choice."},{"id":"LH-10-04-C-003","sp":"KIT","dir":"PUBLIC_REDACTED","text":"Broadcast the excerpts people cleared. Put the original question before the answer. Leave the names out where they asked.","branch":"PUBLIC_REDACTED"},{"id":"LH-10-04-C-004","sp":"INEZ","dir":"PUBLIC_REDACTED","text":"I'll send every participant the final edit before transmission.","branch":"PUBLIC_REDACTED"},{"id":"LH-10-04-C-005","sp":"KIT","dir":"FAMILY_CONTROLLED","text":"Copies to each consenting household. They decide whether anybody else hears theirs.","branch":"FAMILY_CONTROLLED"},{"id":"LH-10-04-C-006","sp":"MARA","dir":"FAMILY_CONTROLLED","text":"Receipt list stays private. I'll prepare separate envelopes.","branch":"FAMILY_CONTROLLED"},{"id":"LH-10-04-C-007","sp":"KIT","dir":"PRIVATE_CORRECTION","text":"File the correction. My statement can identify June's part. Keep her voice and the families' recordings private.","branch":"PRIVATE_CORRECTION"},{"id":"LH-10-04-C-008","sp":"MARA","dir":"PRIVATE_CORRECTION","text":"Your statement joins the record. The restricted material stays restricted.","branch":"PRIVATE_CORRECTION"},{"id":"LH-10-04-C-009","sp":"KIT","dir":"after signing","text":"Her signature's still there."},{"id":"LH-10-04-C-010","sp":"MARA","dir":"gentle, exact","text":"So is yours. Beside what you know now."}],"journal":""},{"key":"10.04.D","title":"Radio outcome","kind":"Play only selected publication route","stage":"","notes":[],"lines":[{"id":"LH-10-04-D-001","sp":"INEZ","dir":"PUBLIC_REDACTED; broadcast","text":"This correction concerns the Mercy Cut clearance record. The phrase 'Mercy empty' answered a question about a truck's cargo bed. It did not confirm that the settlement was empty.","branch":"PUBLIC_REDACTED"},{"id":"LH-10-04-D-002","sp":"TOM","dir":"PUBLIC_REDACTED; archival","text":"Mercy truck, how's your bed?","branch":"PUBLIC_REDACTED"},{"id":"LH-10-04-D-003","sp":"JUNE","dir":"PUBLIC_REDACTED; archival","text":"Mercy empty. Returning to depot.","branch":"PUBLIC_REDACTED"},{"id":"LH-10-04-D-004","sp":"INEZ","dir":"PUBLIC_REDACTED; broadcast","text":"Later calls identified people at the site. The county's amended record now acknowledges that no further on-site confirmation was obtained before clearance proceeded.","branch":"PUBLIC_REDACTED"},{"id":"LH-10-04-D-005","sp":"INEZ","dir":"FAMILY_CONTROLLED; private station recording","text":"The county has amended the clearance record. Families hold their own recordings. They do not owe the rest of us a listening copy.","branch":"FAMILY_CONTROLLED"},{"id":"LH-10-04-D-006","sp":"INEZ","dir":"PRIVATE_CORRECTION; brief public bulletin","text":"A correction to the Mercy Cut clearance file is available from county records. Personal testimony remains restricted at the participants' request.","branch":"PRIVATE_CORRECTION"}],"journal":""},{"key":"10.04.E","title":"The yellow door","kind":"Final cinematic, all endings","stage":"At the garage, Alma stands a yellow door upright in two repaired feet. A brass bell hangs from it. There is no surrounding wall. Kit approaches with the keys or, in departure endings, her bag. Let environment audio carry the pauses.","notes":["He walks around, reaches back and rings. One clean bell strike. No swelling speech."],"lines":[{"id":"LH-10-04-E-001","sp":"KIT","dir":"looking at the bell","text":"There's no wall."},{"id":"LH-10-04-E-002","sp":"ALMA","dir":"adjusting it","text":"I can see that."},{"id":"LH-10-04-E-003","sp":"KIT","dir":"small smile","text":"People can walk round."},{"id":"LH-10-04-E-004","sp":"ALMA","dir":"testing the bell","text":"They'll work it out."},{"id":"LH-10-04-E-005","sp":"DEL","dir":"approaching; amused","text":"That's a very complicated way to leave a door open."},{"id":"LH-10-04-E-006","sp":"KIT","dir":"RUN or COOPERATE; answering","text":"Morning. Where are you going?"},{"id":"LH-10-04-E-007","sp":"DEL","dir":"RUN or COOPERATE","text":"Same place as yesterday. Coming home afterward."},{"id":"LH-10-04-E-008","sp":"ELLIS","dir":"HANDOVER; answering instead","text":"Morning. Kit left the new timetable inside.","branch":"HANDOVER"},{"id":"LH-10-04-E-009","sp":"DEL","dir":"HANDOVER","text":"She did. I checked the return.","branch":"HANDOVER"},{"id":"LH-10-04-E-010","sp":"ALMA","dir":"LEAVE_UNARRANGED; answering instead","text":"Morning, Del. Bus stops Friday. We'll make calls before then.","branch":"LEAVE_UNARRANGED"},{"id":"LH-10-04-E-011","sp":"DEL","dir":"LEAVE_UNARRANGED","text":"I'll bring my notebook.","branch":"LEAVE_UNARRANGED"}],"journal":""},{"key":"10.04.F","title":"The peaches","kind":"Last playable exchange","stage":"Trigger: player picks up the first free-roam delivery slip after the cinematic.","notes":["Music begins after the last line. Player receives free-roam control. Ending card lists actual route outcome and publication choice, never a single morality score."],"lines":[{"id":"LH-10-04-F-001","sp":"ALMA","dir":"if Kit stays","text":"First fare's paid. Don't put it under the seat.","cond":"Kit stays"},{"id":"LH-10-04-F-002","sp":"KIT","dir":"if staying; lifting jar","text":"Peaches?","cond":"staying"},{"id":"LH-10-04-F-003","sp":"ALMA","dir":"if staying","text":"Good ones. Come back with the jar.","cond":"staying"},{"id":"LH-10-04-F-004","sp":"NICO","dir":"if Kit leaves; telephone at safe pull-off","text":"Mum says you've taken the peaches.","cond":"Kit leaves"},{"id":"LH-10-04-F-005","sp":"KIT","dir":"if leaving; smiling","text":"Tell her I'm keeping the jar hostage until she visits.","cond":"leaving"},{"id":"LH-10-04-F-006","sp":"NICO","dir":"if leaving; pleased","text":"She'll come. You've made it about kitchen equipment.","cond":"leaving"}],"journal":""}]}]}],"runtime":[{"id":"R.01","title":"Driving and maintenance","scenes":[{"key":"R.01.A","title":"Kit vehicle observations","kind":"First occurrence of each fault per journey","stage":"","notes":[],"lines":[{"id":"LH-R-01-A-001","sp":"KIT","dir":"fuel low; practical","text":"Next fuel stop. Put it on the route."},{"id":"LH-R-01-A-002","sp":"KIT","dir":"fuel empty; frustration, no shouting","text":"Shit. All right. Safe side first, then the can."},{"id":"LH-R-01-A-003","sp":"KIT","dir":"coolant warning; controlled urgency","text":"Temperature's climbing. Find shade before it cooks."},{"id":"LH-R-01-A-004","sp":"KIT","dir":"oil critically low; decisive","text":"Engine off. I'm not paying for another block."},{"id":"LH-R-01-A-005","sp":"KIT","dir":"flat tyre; safe stop","text":"There it is. Indicator, shoulder, handbrake."},{"id":"LH-R-01-A-006","sp":"KIT","dir":"after successful field repair; pleased","text":"That'll get us home. It still goes on the repair list."},{"id":"LH-R-01-A-007","sp":"KIT","dir":"starter fails; disappointment","text":"Come on. Battery or cable. Check before you keep trying."},{"id":"LH-R-01-A-008","sp":"KIT","dir":"heavy unsecured load; caution","text":"That's moving. Stop and tie it again."},{"id":"LH-R-01-A-009","sp":"KIT","dir":"seat occupied; no irritation","text":"Seat's taken. We need another plan."},{"id":"LH-R-01-A-010","sp":"KIT","dir":"bad visibility; concentration","text":"Slow down. The road doesn't owe me a view."},{"id":"LH-R-01-A-011","sp":"KIT","dir":"near exhaustion; a real decision","text":"Next safe pull-off. Sleep before I start seeing things."},{"id":"LH-R-01-A-012","sp":"KIT","dir":"return after rest; grounded","text":"Water. Mirrors. Start again."}],"journal":""},{"key":"R.01.B","title":"Ellis roadside assistance","kind":"One rescue call per mission checkpoint","stage":"","notes":[],"lines":[{"id":"LH-R-01-B-001","sp":"KIT","dir":"calling from safety","text":"I'm stopped off the road. Truck won't move."},{"id":"LH-R-01-B-002","sp":"ELLIS","dir":"radio; first triage","text":"Are you hurt?"},{"id":"LH-R-01-B-003","sp":"KIT","dir":"if healthy","text":"No. Just expensive.","cond":"healthy"},{"id":"LH-R-01-B-004","sp":"KIT","dir":"if injured","text":"A little. I'm sitting down.","cond":"injured"},{"id":"LH-R-01-B-005","sp":"ELLIS","dir":"if injured; firm","text":"Stay there. Water within reach. Tell me the marker.","cond":"injured"},{"id":"LH-R-01-B-006","sp":"ELLIS","dir":"if healthy; practical","text":"Marker, fault, what you've already tried. In that order.","cond":"healthy"},{"id":"LH-R-01-B-007","sp":"KIT","dir":"giving example location; no exact number","text":"At the last marker I logged. I've sent the position."},{"id":"LH-R-01-B-008","sp":"ELLIS","dir":"acknowledging location","text":"Received. Don't drain the battery proving it's dead."},{"id":"LH-R-01-B-009","sp":"ELLIS","dir":"on arrival; no judgment","text":"Recovery gear first. Tell me the theory while we work."},{"id":"LH-R-01-B-010","sp":"KIT","dir":"accepting help","text":"Fine. My first theory was 'fuck'. The second one's electrical."}],"journal":""},{"key":"R.01.C","title":"Passenger safety","kind":"Trigger on unsafe movement, maximum once per thirty seconds","stage":"","notes":[],"lines":[{"id":"LH-R-01-C-001","sp":"DEL","dir":"bracing without yelling","text":"Ease it down. We've got room to arrive later."},{"id":"LH-R-01-C-002","sp":"ALMA","dir":"firm","text":"Stop if you need to check it. I can wait sitting down."},{"id":"LH-R-01-C-003","sp":"LORNA","dir":"concerned","text":"I'd rather tell work I'm late than have somebody tell them for me."},{"id":"LH-R-01-C-004","sp":"EDIE","dir":"motion sickness; restrained","text":"Can we pull over? I need a minute outside."},{"id":"LH-R-01-C-005","sp":"KIT","dir":"responding at safe stop","text":"We're stopping here. Away-side door when I say."},{"id":"LH-R-01-C-006","sp":"ADA","dir":"trial feedback only","text":"Explain the stop before people start guessing."}],"journal":""}]},{"id":"R.02","title":"Evidence and consent","scenes":[{"key":"R.02.A","title":"Archive interaction","kind":"One line per selected action","stage":"","notes":[],"lines":[{"id":"LH-R-02-A-001","sp":"KIT","dir":"missing source","text":"That's a note about it. I need the actual page."},{"id":"LH-R-02-A-002","sp":"KIT","dir":"correct match","text":"Same date, same truck. Keep them together."},{"id":"LH-R-02-A-003","sp":"KIT","dir":"uncertain interpretation","text":"Could mean that. Doesn't prove it yet."},{"id":"LH-R-02-A-004","sp":"KIT","dir":"private testimony","text":"Marked private. It stays private."},{"id":"LH-R-02-A-005","sp":"INEZ","dir":"radio; unclear audio","text":"Don't fill the gap with the sentence you expect."},{"id":"LH-R-02-A-006","sp":"MARA","dir":"record review","text":"Quote the document, then put your interpretation underneath."},{"id":"LH-R-02-A-007","sp":"NICO","dir":"permission advice","text":"Ask each person. A family doesn't have a single voice."},{"id":"LH-R-02-A-008","sp":"ROSA","dir":"withdrawing a particular detail","text":"Leave that part out. I'm telling you, not a programme."},{"id":"LH-R-02-A-009","sp":"KIT","dir":"accepting withdrawal","text":"Taken out. I'll show you the revised copy."},{"id":"LH-R-02-A-010","sp":"MATEO","dir":"boundary reminder","text":"No recording today."},{"id":"LH-R-02-A-011","sp":"KIT","dir":"agreeing without persuasion","text":"Understood. I'll leave it in the truck."}],"journal":""},{"key":"R.02.B","title":"Lost cargo","kind":"After retrieval","stage":"","notes":[],"lines":[{"id":"LH-R-02-B-001","sp":"KIT","dir":"crate recovered","text":"Label's readable. Let's get it dry."},{"id":"LH-R-02-B-002","sp":"KIT","dir":"damage discovered","text":"It's damaged. I tell them before I ask them to sign."},{"id":"LH-R-02-B-003","sp":"ALMA","dir":"receiving damaged noncritical cargo","text":"Put it on the table. We'll see what can be saved."},{"id":"LH-R-02-B-004","sp":"WES","dir":"replacement supplies","text":"Same invoice, replacement quantity. I'll keep the damaged stock for parts."},{"id":"LH-R-02-B-005","sp":"MANNY","dir":"help carrying","text":"Lift together. Your back doesn't get a repair bay."}],"journal":""}]},{"id":"R.03","title":"Checkpoint recovery","scenes":[{"key":"R.03.A","title":"Sera terms","kind":"Calm state; once per approach","stage":"","notes":[],"lines":[{"id":"LH-R-03-A-001","sp":"SERA","dir":"warning","text":"Stop at the marked line. Tell me what you're carrying."},{"id":"LH-R-03-A-002","sp":"SERA","dir":"paid return; honouring receipt","text":"Number matches. Let them through."},{"id":"LH-R-03-A-003","sp":"SERA","dir":"agreed material delivered","text":"Len measures it. Then the road's yours for the return."},{"id":"LH-R-03-A-004","sp":"LEN","dir":"checking fuel","text":"Seal's intact. Quantity's right."},{"id":"LH-R-03-A-005","sp":"SERA","dir":"no hostile intent before challenge","text":"Keep clear of the work area. We're moving equipment."},{"id":"LH-R-03-A-006","sp":"KIT","dir":"safe retreat","text":"Backing out. Nobody needs a surprise."},{"id":"LH-R-03-A-007","sp":"LEN","dir":"Sera unavailable; handover","text":"Her agreement's in the box. I'll honour what's written."}],"journal":""},{"key":"R.03.B","title":"Pursuit feedback","kind":"Combat-aware; do not play over story scenes","stage":"","notes":["Story Sera lines are suppressed if she is incapacitated; gameplay can use nonverbal crew actions."],"lines":[{"id":"LH-R-03-B-001","sp":"KIT","dir":"real pursuit begins; urgent","text":"They're coming. Watch the turn, not the mirror."},{"id":"LH-R-03-B-002","sp":"KIT","dir":"after real heavy impact; shocked","text":"Fuck! Keep it straight."},{"id":"LH-R-03-B-003","sp":"KIT","dir":"pursuer physically disabled; observation","text":"That one's stopped. Don't go back toward it."},{"id":"LH-R-03-B-004","sp":"KIT","dir":"all pursuit vehicles disabled; breath released","text":"Road's clear behind us. Find somewhere safe."},{"id":"LH-R-03-B-005","sp":"SERA","dir":"pursuer car damaged; shouted to own driver","text":"Pull it off the road! That wheel's gone."},{"id":"LH-R-03-B-006","sp":"LEN","dir":"on foot near stopped vehicle; warning without threat","text":"Stay clear. Fuel's leaking."},{"id":"LH-R-03-B-007","sp":"KIT","dir":"nonlethal capture recovery; drained","text":"Let me check the truck before I drive."},{"id":"LH-R-03-B-008","sp":"SERA","dir":"nonlethal capture release; flat","text":"Take the marked turn. We're finished."}],"journal":""}]},{"id":"R.04","title":"Service and free-roam continuity","scenes":[{"key":"R.04.A","title":"Route messages","kind":"Once per run condition","stage":"","notes":[],"lines":[{"id":"LH-R-04-A-001","sp":"KIT","dir":"late but safe; to passengers","text":"We're behind the sheet. I'm calling the connection at the next safe stop."},{"id":"LH-R-04-A-002","sp":"KIT","dir":"backup confirmed","text":"Your other driver is confirmed. Same destination. I'll tell you where to wait."},{"id":"LH-R-04-A-003","sp":"KIT","dir":"no backup confirmed","text":"I haven't got a replacement yet. You deserve to know that."},{"id":"LH-R-04-A-004","sp":"ADA","dir":"revised trial","text":"Same safety checks. New sheet. Last time stays in the record; this run joins it."},{"id":"LH-R-04-A-005","sp":"LORNA","dir":"improved stop","text":"This is the first bus stop I've used without bringing a torch."},{"id":"LH-R-04-A-006","sp":"DEL","dir":"return pickup made","text":"There you are. Had time to complain to a pigeon."},{"id":"LH-R-04-A-007","sp":"ALMA","dir":"route shared by others","text":"Manny's taking Tuesday. Ask him what he needs before you give him more."},{"id":"LH-R-04-A-008","sp":"ELLIS","dir":"handover complete","text":"Keys and service record are with the new driver. I kept the copy you asked for."},{"id":"LH-R-04-A-009","sp":"KIT","dir":"receiving peaches delivery","text":"Empty jar comes back. That's the whole contract."}],"journal":""},{"key":"R.04.B","title":"After publication","kind":"Selected outcome only, once on next visit","stage":"","notes":[],"lines":[{"id":"LH-R-04-B-001","sp":"ALMA","dir":"PUBLIC_REDACTED","text":"Heard my sister's name without an address attached. That's what I asked for.","branch":"PUBLIC_REDACTED"},{"id":"LH-R-04-B-002","sp":"NICO","dir":"PUBLIC_REDACTED","text":"Someone sent me the programme. I could tell where you'd stopped asking us for more.","branch":"PUBLIC_REDACTED"},{"id":"LH-R-04-B-003","sp":"MATEO","dir":"PUBLIC_REDACTED","text":"You left my bit out. Thank you.","branch":"PUBLIC_REDACTED"},{"id":"LH-R-04-B-004","sp":"ROSA","dir":"PUBLIC_REDACTED","text":"They put the blue photograph up. I went to see it.","branch":"PUBLIC_REDACTED"},{"id":"LH-R-04-B-005","sp":"FERN","dir":"PUBLIC_REDACTED","text":"Ledger's still ugly. At least the right sentences sit beside it.","branch":"PUBLIC_REDACTED"},{"id":"LH-R-04-B-006","sp":"ALMA","dir":"FAMILY_CONTROLLED","text":"My copy's in the drawer. I haven't decided who hears it.","branch":"FAMILY_CONTROLLED"},{"id":"LH-R-04-B-007","sp":"INEZ","dir":"FAMILY_CONTROLLED","text":"Nobody's collecting listenership on this one. That's all right.","branch":"FAMILY_CONTROLLED"},{"id":"LH-R-04-B-008","sp":"MATEO","dir":"FAMILY_CONTROLLED","text":"Mum played hers for my aunt. Mine's still sealed.","branch":"FAMILY_CONTROLLED"},{"id":"LH-R-04-B-009","sp":"NICO","dir":"PRIVATE_CORRECTION","text":"Read the correction. Short enough that people might actually finish it.","branch":"PRIVATE_CORRECTION"},{"id":"LH-R-04-B-010","sp":"MARA","dir":"PRIVATE_CORRECTION","text":"Original and amendment are linked. The restricted recordings remain restricted.","branch":"PRIVATE_CORRECTION"},{"id":"LH-R-04-B-011","sp":"OWEN","dir":"any outcome; optional later meeting","text":"I read the final record. There's nothing I need you to take out."},{"id":"LH-R-04-B-012","sp":"KIT","dir":"to Owen; steady","text":"Good."},{"id":"LH-R-04-B-013","sp":"ELLIS","dir":"any outcome; later workshop","text":"I wrote down what I actually saw. Turns out I can still sleep afterward."}],"journal":""}]}]};
